INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(5, 'STIE WIDYA WIWAHA  WISUDA PROGRAM SARJANA dan PASCA SARJANA Periode Tahun 2021', 'wisuda-stie-ww', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Wisuda merupakan proses pelantikan kelulusan bagi Mahasiswa yang menempuh pendidikan di Program Sarjana dan Pasca Sarjana di STIE Widya Wiwaha Yogyakarta, yang berarti Alumni STIE Widya Wiwaha mulai hari ini secara sah berhak menyandang gelar akademik </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">&ldquo;Sarjana </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Akuntansi (S.Ak.) bagi lulusan S1 Akuntansi, Sarjana Manajemen (S.M.) bagi lulusan S1 Manajemen serta Magister Manajemen (M.M.) bagi lulusan Program S2 Pasca Sarjana&rdquo;. </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">W</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">isuda ini juga sekaligus sebagai bentuk pernyataan resmi akan </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">meningkatnya </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">derajat tanggung jawab sebagai konsekuensi gelar kesarjanaan yang disandang. Maka, pergunakanlah keahlian dan kompetensi yang sudah Alumni STIE Widya Wiwaha peroleh dengan sebaik-baiknya serta senantiasa menjaga nama baik almamater. </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">D</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">engan rasa persaudaraan yang sangat kuat di antara sesama alumni STIE Widya Wiwaha, perkuat jaringan alumni dan buktikan alumni STIE Widya Wiwaha bisa berjaya</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\"> dimana-mana</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:red\">.</span></span></span></span> </span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Pada wisuda kali ini, STIE Widya Wiwaha mewisuda 4</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"color:black\">19</span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\"> lulusan yang terdiri dari Program studi S1 Manajemen 149 Wisudawan, Program Studi Akuntansi 140 Wisudawan serta Pogram Pasca Sarjana (Magister Manajemen) berjumlah 130 Wisudawan.</span></span></span></span> <span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Dengan diwisudanya sarjana dan magister baru, maka sampai hari ini STIE Widya Wiwaha sudah meluluskan &nbsp;11.228 Sarjana dan 3.158 Magister. </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Dalam sambutannya, Ketua STIE Widya Wiwaha Yogyakarta, Bapak </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Drs. </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">M</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">u</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">h</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">ammad</span></span></span></span> <span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Subkhan MM.</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">, </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">mengucapkan terimakasih kepada </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">segenap </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">keluarga wisudawan/wisudawati, atas kepercayaannya kepada STIE Widya Wiwaha dan kerjasamanya selama ini. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">&ldquo;Kita sedang memasuki era baru, Era Revolusi Industri 4.0 dimana perubahan cepat sedang terjadi dengan dicirikan : kegiatan manufaktur yang terintegrasi dengan teknologi wireless dan big data secara masif. Perubahan yang cepat sedang terjadi, dalam beberapa tatanan kehidupan berorganisasi dan bisnis. Revolusi ini secara fundamental dapat mengubah cara kita hidup, bekerja, dan berhubungan satu dengan yang lain. Perkembangan teknologi yang pesat cepat atau lambat akan berpengaruh pada permintaan tenaga kerja di masa depan. Ke depan permintaan tenaga kerja bergeser. Industri akan cenderung memilih tenaga kerja terampil menengah dan tinggi (</span></span></span></span><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">middle and highly-skilled labor</span></span></em><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">) ketimbang tenaga kerja kurang terampil (</span></span></span></span><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">less-skilled labor</span></span></em><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">) karena perannya dalam mengerjakan pekerjaan repetisi dapat digantikan dengan otonomisasi dan otomatisasi. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Mengutip dari&nbsp;hasil Forum Internasional tahunan yang bertemakan &ldquo;<em>Mastering the Fourth Industrial Revolution</em>&rdquo;, bahwa ke depan akan ada banyak jenis pekerjaan yang hilang dan tergantikan oleh fungsi robot atau&nbsp;<em>artificial intelligence</em>. Para tenaga kerja manusia pun tidak menutup kemungkinan akan menghadapi jenis pekerjaan baru yang tidak pernah terpikirkan sebelumnya, sehingga revolusi ini mau tak mau menuntut kita untuk terus mengembangkan&nbsp;<em>skill&nbsp;</em>yang sekiranya dapat bermanfaat serta mumpuni di masa depan&rdquo;, demikian penjelasan Bapak Moh Subkhan, Ketua STIE Widya Wiwaha</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Selain itu Moh, Subkhan menjelaskan bahwa </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">ketrampilan yang harus dimiliki </span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">oleh wisudawan dan wisudawati baik program S1 maupun S2 dalam </span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">memasuki pasar dunia kerja saat ini dan </span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">yang akan datang</span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">, menurut </span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Future of Jobs Reports, World Economic Forum adalah</span></span></span> <strong><span style=\"font-size:12.0pt\"><span style=\"color:black\">Complex problem solving</span></span></strong><strong><span style=\"font-size:12.0pt\"><span style=\"color:black\"> atau </span></span></strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">merupakan kemampuan penyeleasaian masalah, <strong>Critical thinking</strong></span></span></span><strong> </strong><em><span style=\"font-size:12.0pt\"><span style=\"color:black\">berupa </span></span></em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">kemampuan berpikir kritis, <strong>Creativity</strong></span></span></span><strong> </strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">adalah kemampuan dan kemamuan untuk terus berinovasi, <strong>People management</strong></span></span></span><em><span style=\"font-size:12.0pt\"><span style=\"color:black\">, yaitu </span></span></em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">kemampuan untuk mengatur, memimpin dan memanfaatkan sumber daya manusia secara tepat sasaran dan efektif, <strong>Coordinating with other</strong></span></span></span><strong> </strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Kemampuan untuk kerjasama tim, <strong>Emotion intelligence</strong></span></span></span><strong><span style=\"font-size:12.0pt\"><span style=\"color:black\"> atau </span></span></strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">kecerdasan emosional, <strong>Judgment and decision making</strong></span></span></span><strong> </strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">adalah&nbsp;kemampuan untuk menarik kesimpulan atas situasi yang dihadapi , <strong>Service orientation</strong></span></span></span> <span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">adalah keinginan untuk membantu dan melayani orang lain, <strong>Negotiation</strong></span></span></span><strong> </strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">merupakan kemampuan berbicara, bernegosiasi, dan meyakinkan orang dalam aspek pekerjaan dan <strong>Cognitive flexibility</strong></span></span></span><strong><span style=\"font-size:12.0pt\"><span style=\"color:black\">, </span></span></strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">adalah&nbsp;kemampuan untuk menyusun secara spontan suatu pengetahuan, dalam banyak cara, dalam memberi respon penyesuaikan diri untuk secara radikal merubah tuntutan situasional. </span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Sedangkan Ketua Yayasan Widya Wiwaha Yogyakarta, </span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Drs. Ayik Muhammad Al Hasny, MM</span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"> menegaskan </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">hal yang sama, </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">bahwa <span style=\"background-color:white\"><span style=\"color:black\">Menyitir sebagian misi Kementrian Riset dan Teknologi antara lain: Pembangunan IPTEK 2025 yaitu mewujudkan sistem inovasi nasional yang tangguh guna meningkatkan daya saing bangsa di Era Global. Diharapkan lulusan STIE Widya Wiwaha dapat bersaing dan berinovasi dengan kompetensi yang dimiliki. Kami juga yakin bahwa bertambahnya ilmu pengetahuan dan bertambahnya gelar dibelakang nama saudara semuanya akan meningkatkan dedikasi , kinerja dan prestasi saudara semuanya dalam menghadapi Era Global.</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Selain itu juga ucapan selama juga diucapkan oleh Direktur Program Magister Manajemen kepada Lulusan Program Magister Manajemen STIE Widya Wiwaha Yogyakarta, beliau berpesan dan berharap para wisudawan/wisudawati selain ilmu yang sudah diperoleh di program Magister Managemen STIE Widya Wiwaha, Alumni Program Magister semua tetap dapat terus menambah ilmu pengetahuannya. Seperti ungkapan yang menyebutkan bahwa kewajiban kita untuk menuntut ilmu mulai dari lahir hingga liang lahat, karena dengan mempunyai ilmu, menghayati dan mengamalkannya; Tuhan sudah berjanji akan mengangkat mereka dengan beberapa derajat. Ini semua adalah untuk anda dalam menyongsong hari depan dengan karir yang lebih sukses, lebih baik, lebih baroqah, dan penuh kebahagiaan bersama keluarga</span></span></span></span><span style=\"font-size:12.0pt\"><span style=\"background-color:white\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">.</span></span></span></span></span></span></p>\r\n', 'STIE WIDYA WIWAHA \r\nWISUDA PROGRAM SARJANA dan PASCA SARJANA\r\nPeriode Tahun 2021, 27 November 2021\r\nDi Hotel Inna Malioboro\r\n', '05-09-2017', 'news-7.png', 1, 'Arif Suwarjono', 7393, 'Wisuda Periode 2021', '', ''),
(6, 'RANGAKAIN LUSTRUM VIII', 'rangakain-lustrum-viii', '<p>Halo kak, udah ga sabar nunggu acara lustum besok ya? ini mimin kasih bocoran rangkaian acaranya. Semoga acara lustrum besok sukses dan lancar Aamiin.. mohon doanya kak..</p>\r\n', 'Halo kak, udah ga sabar nunggu acara lustum besok ya? ini mimin kasih bocoran rangkaian acaranya. Semoga acara lustrum besok sukses dan lancar Aamiin.. mohon doanya kak..', '12-04-2022', 'news-6.png', 1, 'Prafidya', 2463, 'RANGAKAIN LUSTRUM VIII', '', ''),
(11, 'STIE WW Training', 'ww-training', '<p style=\"text-align:center\"><img alt=\"\" src=\"http://stieww.ac.id/assets/uploads/page-banner-12.jpeg\" style=\"height:500px; width:500px\" /></p>\r\n\r\n<p style=\"text-align:center\"><strong>Brevet Pajak A&amp;B STIE Widya Wiwaha Yogyakarta</strong><br />\r\nBatch 2 (April-Juni 2022)</p>\r\n\r\n<p style=\"text-align:center\"><strong>Executive Class</strong><br />\r\n- Hari: setiap Sabtu&nbsp;<br />\r\n- Pukul: 08.00-15.00 WIB<br />\r\n- Kelas: Online Zoom Meeting</p>\r\n\r\n<p style=\"text-align:center\"><strong>Instruktur:</strong><br />\r\n- Praktisi Perpajakan (IKPI) dan Profesi Akuntan&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><strong>Fasilitas:</strong><br />\r\n- Ilmu bermanfaat<br />\r\n- E-Modul &amp; E-Certificate langsung dari IKPI Pusat</p>\r\n\r\n<p style=\"text-align:center\"><strong>Biaya Registrasi:</strong><br />\r\n- Rp1.250.000,- (Umum)<br />\r\n- Rp750.000,- (Mahasiswa STIE WW)</p>\r\n\r\n<p style=\"text-align:center\"><strong>Pendaftaran&nbsp;</strong><br />\r\n<a href=\"https://forms.gle/g4hRrAccrosNDjqA7\">https://forms.gle/g4hRrAccrosNDjqA7</a></p>\r\n\r\n<p style=\"text-align:center\"><strong>Contact Person:</strong><br />\r\nNI&#39;matul Hasanah <a href=\"http://wa.me/628995880643\">wa.me/628995880643</a></p>\r\n\r\n<p style=\"text-align:center\"><strong>Info lebih lanjut:</strong><br />\r\n<a href=\"https://www.instagram.com/p/CX2z7g2h_8I/?utm_source=ig_web_copy_link\">https://www.instagram.com/p/CX2z7g2h_8I/?utm_source=ig_web_copy_link</a></p>\r\n', 'Brevet Pajak A&B STIE Widya Wiwaha Yogyakarta, Batch 2 (April-Juni 2022), Langsung dengan Praktisi Perpajakan (IKPI) dan Profesi Akuntan ', '14-04-2022', 'news-11.jpeg', 2, 'Prafid', 2821, 'STIE WW Training', '', ''),
(12, 'LOMBA BUSINES PLAN', 'lomba-busines-plan', '<p style=\"text-align:center\">Halo buat kamu pelajar SMA/SMK/MA/MK Seluruh Indonesia&nbsp;<br />\r\nApa kabarnya? Semoga teman-teman selalu dalam keadaan sehat yahh!&nbsp;<br />\r\n<br />\r\nAda kabar gembira nih teman-teman. Kami dari panitia Lustrum STIE Widya Wiwaha dengan bangga mengumumkan salah satu rangkaian lomba Lustrum STIE Widya Wiwaha yaitu lomba Business Plan dengan tema <strong>&quot;Green Economy&quot; </strong>.<br />\r\nBuat teman-teman yang berminat mengikuti lomba yukk langsung simak yaa :<br />\r\n<br />\r\n<strong>Timeline</strong><br />\r\n1. Pendaftaran : 15 - 27 April<br />\r\n2. Pengumpulan Proposal : 28 April - 27 Mei<br />\r\n3. Tahap Seleksi Proposal : 28 Mei - 5 Juni<br />\r\n4. Pengumuman Finalis : 6 Mei<br />\r\n5. Presentasi Proposal : 17 Juni<br />\r\n<br />\r\n<strong>Reward</strong><br />\r\n1. Hadiah jutaan rupiah bagi juara I - III + Thropy dan sertifikat<br />\r\n2. Sertifikat untuk setiap peserta lomba<br />\r\n<br />\r\nJadi nunggu apalagi nih teman - teman? Yukk langsung daftarkan kelompok kalian yaa!<br />\r\n<br />\r\nLink Pendaftaran &amp; Panduan Lomba :<br />\r\nhttps://linktr.ee/bpcSTIEWW2022</p>\r\n', 'Kami dari panitia Lustrum STIE Widya Wiwaha dengan bangga mengumumkan salah satu rangkaian lomba Lustrum STIE Widya Wiwaha yaitu lomba Business Plan dengan tema \"Green Economy\" ', '19-04-2022', 'news-12.png', 1, 'Prafid', 2435, 'LOMBA BUSINES PLAN', '', ''),
(13, 'Seminar Nasional dan Call Paper 2022', 'seminar-nasional-dan-call-paper-2022', '<p style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong><span style=\"font-size:18.0pt\">DAFTAR ISI</span></strong></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><a href=\"http://eprint.stieww.ac.id/1742/7/Halaman%20Depan.pdf\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong>SAMBUTAN KETUA PANITIA, iii</strong></span></span></a></p>\r\n\r\n<p style=\"text-align:justify\"><a href=\"http://eprint.stieww.ac.id/1742/7/Halaman%20Depan.pdf\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong>SAMBUTAN KETUA STIE WIDYA WIWAHA, iv</strong></span></span></a></p>\r\n\r\n<p style=\"text-align:justify\"><a href=\"http://eprint.stieww.ac.id/1742/7/Halaman%20Depan.pdf\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong>DAFTAR ISI, v</strong></span></span></a></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1741/\">Pengaruh Political Skill, Lingkungan Kerja Dan Motivasi Pada Kinerja</a>. <strong>Dwi Novitasari, 1</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1742/\">Pengaruh Digital Marketing Terhadap Citra SMK Bumantara Muntilan Kabupaten Magelang.</a> <strong>Hendrix Tiyas Eka Kusuma, 23</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1743/\">Optimalisasi Bhabinkamtibmas Terhadap <em>Tour Of Duty</em> Dan <em>Tour Of Area</em> Di Polres Magelang.</a> <strong>Sunandar, 46</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1744/\">Pengaruh Motivasi Dan Beban Kerja Terhadap Kinerja Karyawan Dengan Kepuasan Kerja Sebagai Variabel Mediasi (Studi pada Karyawan Outsourcing di RSUP Dr. Sardjito).</a> <strong>Arsanto Darmawan dan Suhartono, 61</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1745/\">Pengaruh Pusat Kegiatan Gugus Dan Sertifikasi Terhadap Peningkatan Literasi Digital Guru Taman Kanak-Kanak Di Masa Pandemi Covid-19<em>.</em></a> <strong>Dwi Lestari, 73</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1746/\">Pengaruh Pendapatan Asli Daerah, Dana Perimbangan, dan Belanja Daerah Terhadap Kinerja Keuangan Pemerintah Daerah Pada Kabupaten/Kota Di Provinsi Jawa Tengah dan DIY Tahun 2016-2020.</a> <strong>Dyah Ayu Putri Ermawati, Nur Widiastuti dan Zulkifli, 90</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1747/\">Faktor Penentu Manajemen Laba.</a> <strong>Fatonah dan Taswan</strong><strong>, 112</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1748/\">Pengaruh Sistem Pengendalian Intern Pemerintah Dan Aksesibilitas Laporan Keuangan Terhadap Akuntabilitas Pengelolaan Keuangan Dana Desa (Studi Kasus Kelurahan Margokaton Kabupaten Sleman Yogyakarta).</a>&nbsp;<strong>Lilik Ambarwati dan Ulva Nur Novia Handayani, 129</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1749/\">Ekonomi Digital Di Indonesia, Peluang Dan Strategi.</a> <strong>Nur Widiastuti, 148</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1750/\">Strategi Inovasi: Bagaimana Usaha Kecil Perempuan Bisa Bertahan Hidup Di Masa Pandemi.</a> <strong>Priyastiwi, 168</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1699/\">Pengaruh Work From Home (WFH) Dan Kepuasan Kerja Terhadap Produktivitas Kerja.</a>&nbsp;<strong>Riska Anggelina dan Uswatun Chasanah, 184</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1752/\">Efektifitas Peran Kader Di Kelompok Kegiatan BKB Melati 9 RW 9 Kelurahan Warungboto Kemantren Umbulharjo Kota Yogyakarta</a><em><a href=\"http://eprint.stieww.ac.id/1752/\">.</a> </em><strong>Yulia Suryani Dewi, 196</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1753/\">Pengaruh Distribusi, Promosi Dan Kualitas Layananan Terhadap Keputusan Pembelian Pada Online Shop Shopee Selama Pandemi Covid-19.</a> <strong>Lubna Laila dan Nita Fitriana, 213</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1754/\">Pengaruh Profitabilitas, Likuiditas, Ukuran Perusahaan, Dan Leverage Terhadap Pengungkapan Internet <em>Financial Reporting</em> Pada Perusahaan Indeks LQ45 Yang Terdaftar Di Bursa Efek Indonesia (BEI) Periode Tahun 2015-2019.</a> <strong>Sulastiningsih dan Ajeng Fazri Rahmasari, 229</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1755/\">Pemberdayaan, Motivasi Dan Peningkatan Kinerja Karyawan Pada Masa Pandemi Covid-19 (Studi Kasus Pada Toko Beibyqu-Baby Shop Bantul Yogyakarta).</a> <strong>Futri Khairunnisah dan Evi Rosalina Widyayanti, 247</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1760/\">Pengaruh Literasi Keuangan, Digital Marketing, Brand Image Dan Word Of Mouth Terhadap Minat Generasi Z Pada Bank Syariah (Studi Kasus Di Bank Syariah Kabupaten Sleman).</a> <strong>Muhammad Subkhan, 262</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1755/\">Penerapan Strategi Business Model Canvas (BMC) Dalam Upaya Bertahan Hidup UMKM Dimasa Pandemi Covid-19 Di Daerah Istimewa Yogyakarta.</a> <strong>Evi Rosalina Widyayanti &amp; Insiatiningsih, 277</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Analisis Swot Dalam Menentukan Strategi Keberlanjutan Usaha Dapur Warna Di Era New Normal. <strong>Ratih Safitri Sulistyowati &amp; Qurrota Ayunina, 298</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1698/\">Strategi Pemasaran, Inovasi Produk, Dan Minat Beli Untuk Meningkatkan Kinerja Pemasaran Umkm Pada Pedagang Kaki Lima Pakaian Batik Di Malioboro</a><strong><a href=\"http://eprint.stieww.ac.id/1698/\">.</a> Muhammad Robi Nurwahyudi dan Mareta Windi Astuti, 319</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1825/\">Peran E-Learning Training Dan Motivasi Pada Kinerja Pegawai Di Masa Pandemi Covid-19</a><strong><a href=\"http://eprint.stieww.ac.id/1825/\">.</a> Sofiati dan Dewi Larasati, 342 </strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><a href=\"http://eprint.stieww.ac.id/1841/\">Analisis Anteseden Dan Konsekuen Kepuasan Pelanggan Pada Rumah Makan Cepat Saji Dengan Pendekatan Teori Stimulus-Organism-Response (SOR).</a> <strong>Muhammad Mathori dan Uswatun Chasanah, 358</strong></span></span></li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n', 'Prosiding Seminar Nasional dan Call Paper 2022', '18-12-2021', 'news-13.jpeg', 1, 'Arif', 2348, 'Seminar Nasional', '', ''),
(14, 'Lowongan Kantor Pos Yogyakarta Juni 2022', 'lowongan-kantor-pos-yogyakarta-juni-2022', '<p>Lowongan Kantor Pos Yogyakarta Juni 2022</p>\r\n', 'Lowongan Kantor Pos Yogyakarta Juni 2022', '09-06-2022', 'news-14.jpeg', 5, 'STIE WW', 2090, '', '', ''),
(15, 'Gelar Reuni Lintas Angkatan, Alumni STIE WW Perkuat Kolaborasi', 'gelar-reuni-lintas-angkatan-alumni-stie-ww-perkuat-kolaborasi', '<p><strong>KBRN</strong>,&nbsp;<strong>Yogyakarta</strong>: Pengurus Alumni Pusat dan STIE Widya Wiwaha berkolaborasi menyelenggarakan Reuni Lintas Angkatan dalam rangka Dies Natalis ke-40 STIE Widya Wiwaha di University Hotel Yogyakarta. Reuni lintas generasi yang berlangsung 4-5 Juni itu dihadiri alumni angkatan pertama tahun 1982 hingga angkatan termuda tahun 2017.</p>\r\n\r\n<p>Reuni yang dibuka Sabtu (4/6/2022) siang, juga diikuti alumni Sekolah Tinggi Ilmu Ekonomi Widya Wiwaha atau STIE WW yang terbilang sukses. Salah satu di antaranya adalah Wakil Bupati Kebumen, Ristawati Purwaningsih, SST, MM.</p>\r\n\r\n<p>Ristawati berharap kebersamaan tak hanya terjalin saat reuni saja, tapi selalu terjalin hari-hari ke depan sehingga selalu berguna untuk masyarakat dan lingkungan sekitar.</p>\r\n\r\n<p>&quot;Almamater punya kewajiban untuk mendharmabaktikan kepada kampus agar semakin maju dan berada di hati masyarakat,&quot; tuturnya, Minggu (5/6/2022) siang.</p>\r\n\r\n<p>Wakil Bupati yang merupakan pasangan hidup dari H Cipto Waluyo itu juga menginginkan kekuatan alumni dapat dimanfaatkan untuk mengangkat citra almamater STIE WW.</p>\r\n\r\n<p>&quot;Kita punya latar belakang yang bermacam-macam, bisa berkolaborasi dan mendukung satu sama lain sehingga menjadi kuat dan bermanfaat bersama untuk masyarakat Kebersamaan menjadi modal awal, pondasi untuk meraih cita-cita bersama,&quot; sebut Ristawati.</p>\r\n\r\n<p>Wanita yang merupakan alumni Magister Manajemen STIE WW itu juga berharap agar kampus semakin maju dan bermanfaat untuk masyarakat, seluruh alumni harus mau dan mampu memberdayakan adik-adik mahasiswa yang masih berproses menuju jenjang wisuda.</p>\r\n\r\n<p>&quot;Banyak alumni di segala bidang, akuntan, perbankan, politisi, dan pengusaha. Semua dalam kontribusi membangun bangsa dan mengangkat nama baik kampus,&quot; tutur wakil dari Bupati Kebumen Arif Sugiyanto itu.</p>\r\n\r\n<p>Sementara itu, Ketua Panitia Reuni, Dr Misnen Ardiansyah mengatakan saat ini alumni STIE WW banyak berkecimpung di berbagai profesi dengan beragam kontribusi untuk bangsa.</p>\r\n\r\n<p>&quot;Kita ingin berkontribusi melalui ikatan alumni. Kami ingin semacam bela beli kepada teman-teman alumni yang mempunyai bisnis. Kami akan mengutamakan dari alumni, tentu itu akan bermanfaat,&quot; katanya. (ros)</p>\r\n\r\n<p><a href=\"https://www.bernas.id/2022/06/148278/ratusan-alumni-stie-widya-wiwaha-hadiri-reuni-lintas-angkatan-di-jogja/\" target=\"_blank\">https://www.bernas.id/2022/06/148278/ratusan-alumni-stie-widya-wiwaha-hadiri-reuni-lintas-angkatan-di-jogja/</a></p>\r\n', 'Pengurus Alumni Pusat dan STIE Widya Wiwaha berkolaborasi menyelenggarakan Reuni Lintas Angkatan dalam rangka Dies Natalis ke-40 STIE Widya Wiwaha di University Hotel Yogyakarta. Reuni lintas generasi yang berlangsung 4-5 Juni itu dihadiri alumni angkatan pertama tahun 1982 hingga angkatan termuda tahun 2017.', '10-06-2022', 'news-15.jpg', 1, 'STIE WW', 2289, '', '', ''),
(16, 'Ratusan Alumni STIE Widya Wiwaha Hadiri Reuni Lintas Angkatan Di Jogja', 'ratusan-alumni-stie-widya-wiwaha-hadiri-reuni-lintas-angkatan-di-jogja', '<p><strong>SLEMAN, BERNAS.ID</strong>&nbsp;&ndash; Pengurus Alumni Pusat dan STIE Widya Wiwaha berkolaborasi menyelenggarakan Reuni Lintas Angkatan dalam rangka Dies Natalis ke-40 STIE Widya Wiwaha di University Hotel, tanggal 4-5 Juni 2022. Reuni lintas generasi dihadiri dari alumni angkatan pertama tahun 1982 sampai dengan angkatan termuda tahun 2017.</p>\r\n\r\n<p>Salah satu alumni, Wakil Bupati Kebumen, Ristawati Purwaningsih, SST, MM mengatakan, kebersamaan tidak hanya terjalin saat reuni saja, tapi selalu terjalin hari-hari ke depan sehingga selalu berguna untuk masyarakat dan lingkungan sekitar.</p>\r\n\r\n<p>&ldquo;Almamater punya kewajiban untuk mendharmabaktikan kepada kampus agar semakin maju dan berada di hati masyarakat,&rdquo; tuturnya, Minggu (5/6/2022).</p>\r\n\r\n<p>&ldquo;Kita punya latar belakang yang bermacam-macam, bisa berkolaborasi dan mendukung satu sama lain sehingga menjadi kuat dan bermanfaat bersama untuk masyarakat Kebersamaan menjadi modal awal, pondasi untuk meraih cita-cita bersama,&rdquo; imbuhnya.</p>\r\n\r\n<p>Untuk itu, agar kampus semakin maju dan bermanfaat untuk masyarakat, Ristawati berharap seluruh alumni harus memberdayakan adik-adiknya mahasiswa yang masih berproses di sehingga nanti mendapatkan pekerjaan dan berdaya ekonominya sehingga mendapatkan kesejahteraan.</p>\r\n\r\n<p>&ldquo;Banyak alumni di segala bidang, akuntan, perbankan, politisi, dan pengusaha. Semua dalam kontribusi membangun bangsa dan mengangkat nama baik kampus,&rdquo; imbuhnya.</p>\r\n\r\n<p>Ketua Panitia Reuni, Dr Misnen Ardiansyah mengatakan, alumni banyak berkecimpung di berbagai profesi dengan beragam kontribusinya kepada bangsa. &ldquo;Kita ingin berkontribusi melalui ikatan alumni. Kami ingin semacam bela beli kepada teman-teman alumni yang mempunyai bisnis. Kami akan mengutamakan dari alumni, tentu itu akan bermanfaat,&rdquo; katanya.</p>\r\n\r\n<p>Ketua STIE Widya Wiwaha, Drs Mohammad Subhan, MM mengatakan, sudah sekian lama, temu alumni yang besar belum terlaksana. Ia pun berharap kolaborasi seluruh elemen dengan latar belakangnya, dapat membawa kebaikan kepada alumni dan kampus.</p>\r\n\r\n<p>&ldquo;Sampai saat ini, sudah ada 11.600 alumni dari S1 dan 3500 dari program magister,&rdquo; katanya.</p>\r\n\r\n<p>&ldquo;Alumni yang sudah berhasil akan bisa berkolaborasi dengan kami. Mahasiswa yang masih berproses melalui Program Kampus Merdeka akan bisa dikolaborasikan dengan alumni. Akan kita tindaklanjuti dengan program-program riil bersama alumni,&rdquo; imbuhnya.</p>\r\n\r\n<p>Ia pun berharap para alumni yang berhasil dan tersebar akan bisa berkolaborasi dengan alumni yang mungkin belum mendapat pekerjaan.&nbsp;<strong>(jat)</strong></p>\r\n\r\n<p><a href=\"https://www.bernas.id/2022/06/148278/ratusan-alumni-stie-widya-wiwaha-hadiri-reuni-lintas-angkatan-di-jogja/\" target=\"_blank\">https://www.bernas.id/2022/06/148278/ratusan-alumni-stie-widya-wiwaha-hadiri-reuni-lintas-angkatan-di-jogja/</a></p>\r\n', 'Pengurus Alumni Pusat dan STIE Widya Wiwaha berkolaborasi menyelenggarakan Reuni Lintas Angkatan dalam rangka Dies Natalis ke-40 STIE Widya Wiwaha di University Hotel, tanggal 4-5 Juni 2022. Reuni lintas generasi dihadiri dari alumni angkatan pertama tahun 1982 sampai dengan angkatan termuda tahun 2017.', '10-06-2022', 'news-16.jpg', 1, 'STIE WW', 2830, '', '', ''),
(17, 'Gagal SBMPTN?Ayo daftarkan skor UTBK mu di STIE Widya Wiwaha', 'gagal-sbmptn-ayo-daftarkan-skor-utbk-mu-di-stie-widya-wiwaha', '<p><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Lembaga Tes Masuk Perguruan Tinggi (LTMPT) telah mengumumkan hasil Seleksi&nbsp; Bersama Masuk Perguruan Tinggi (SBMPTN) 2022 pada Kamis (23/6/2022) pukul 15.00 WIB. Di Jogja sendiri terdapat lima Perguruan tinggi (PTN)&nbsp; yaitu Universitas Gadjah Mada (UGM), Universitas Negeri Yogyakarta (UNY), Universitas Pembangunan Nasional Veteran Yogyakarta (UPNVY), Institut Seni Indonesia (ISI) Yogyakarta dan Universitas Islam Negeri (UIN) Sunan Kalijaga.</span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"><strong><img alt=\"\" src=\"https://lh5.googleusercontent.com/8EFXqhCL3GHh9O7q3oDf4ICSPFk8QeQczQhMfHxst5poLmw_gDiUlkshIwsQO8zjjaEOpqWCGyfVwCF7zF8IkvNA5ppcpU6TSnclH-ucmbS8NNXVbn1EPrCQozvpVEey9ye9V_Ig89b_7zzVQw\" style=\"height:216px; width:420px\" /></strong></span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:8pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Gb.contoh pengumuman tidak lulus SBMPTN</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">&nbsp;&nbsp;Sebanyak 2.716 calon mahasiswa baru dinyatakan diterima di UGM melalui jalur SBMPTN dari total&nbsp; pendaftar yaitu 50.222. Lalu, UNY keseluruhan yang diterima&nbsp; adalah sebanyak 2.334 calon mahasiswa dari total pendaftar 42.425. Kemudian, UPNVY&nbsp; sebanyak 2.448 pendaftar dinyatakan diterima dari total pendaftar 3.728.&nbsp; Selanjutnya, ISI Yogyakarta sebanyak 481 calon mahasiswa diterima dan yang terakhir adalah UIN Sunan Kalijaga, sebanyak 729 calon mahasiswa diterima.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Untuk total peserta SBMPTN tahun 2022 sendiri yakni sebanyak&nbsp; 800.852 peserta, dan yang diterima sebanyak 192.810 peserta.Yang artinya ada 608.042 pendaftar yang tidak diterima. Bagi mereka yang lolos atau tidak lolos, bisa mencetak sertifikat UTBK yang didalamnya tertera skor masing masing peserta. Bagaimana&nbsp; hasil UTBKnya</span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"><em>?</em></span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"> Selamat bagi yang diterima. Bagi kamu yang belum lulus, tak perlu berkecil hati . Gagal SBMPTN&nbsp; bukan halangan untuk kuliah atau menambah kemampuan diri. Bagi kalian yang gagal lulus SBMPTN&nbsp; tidak perlu berlarut-larut dengan hasilnya. Seperti kata pepatah Romawi &lsquo;&rsquo;Banyak jalan menuju Roma&rsquo;&rsquo; artinya masih banyak jalan untuk mencapai kesuksesan. Masih ada cara lain untuk masuk perguruan tinggi. Saat ini yang terpenting adalah bagaimana diri kita sendiri menyikapi hasil SBMPTN yang tak sesuai harapan.&nbsp;</span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"><img alt=\"C:\\Users\\ASUS\\Downloads\\dftr pake niali utbk stie ww 1.jpg\" src=\"https://lh5.googleusercontent.com/dZsmiNNKbJkLUlFPvp02pyIp7Umfs2fN77Zb0o2ZVXJ_f7xSaOJBX2__iJXC0VfFgFNXjHcWoSY1uTZx3kYYyyoEz3zZk_QeovyYdfJEYO-wcadNf_IaOrssc-yKVdAcgmlLDF956nLjko_1nA\" style=\"height:287px; width:339px\" /></span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Merasa sedih, itu hal&nbsp; wajar. Namun apakah kamu memang gagal? Terlepas dari pendapat orang lain, pada kenyataannya UTBK-SBMPTN hanyalah salah satu jalur masuk kuliah. Masih ada jalur-jalur lain untuk masuk kuliah. Kamu juga masih bisa mengikuti&nbsp; Seleksi Mandiri di kampus swasta. Salah satu kampus swasta di Jogja yang membuka jalur&nbsp; beasiswa dengan nilai UTBK adalah STIE Widya Wiwaha. Manfaatkan nilai UTBK mu untuk mendapatkan Beasiswa di STIE Widya Wiwaha.Yuk kuliah di STIE Widya Wiwaha dengan menggunakan skor UTBK mu jangan cuma anggurin nilainnya.&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"><img alt=\"C:\\Users\\ASUS\\Downloads\\dftr pake niali UTBK stie ww 2.jpg\" src=\"https://lh5.googleusercontent.com/40Gm_ytHI44GcnLEBWIeG8xq6gR6b29RdAlKa56Ld-NMxtvCpkDG3O143OAWwZSH-zJdEG60hUOg_wXbrodfUQJEn3onRADG17T2-tNdytXmwq7ogAMEb890v5RKXhOaX1kmTkHEXEOHAUbjow\" style=\"height:297px; width:327px\" /></span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Berapa skor kamu nih? nah, jika nilai rata rata UTBK kamu lebih dari 651 maka SPA FREE atau 100% potongan SPA untukmu,dan tidak hanya itu untuk SPP sebesar 500.000 saja.. Kemudian, untuk skor rata-rata UTBK 551-650 hanya akan terkena SPA 25 %&nbsp; dengan SPP 500.000 saja. Dan selanjutnya untuk skor dengan rata- rata 451-550 hanya terkena SPA sebesar 50% dan SPP tetap. Tapi rata rata skor utbk ku dibawah 400, gimana dong? Tenang!&nbsp; Bagi yang memiliki rata-rata skor UTBK&nbsp; antara 351-450 masih bisa mendaftar dan mendapat ,potongan yaitu&nbsp; terkena SPA 75 dengan SPP tetap.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Untuk tahapan pendaftaran caranya sangat mudah yaitu mendaftarkan diri anda di website </span></span></span><a href=\"about:blank\" style=\"text-decoration:none\"><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#0000ff\">stieww.ac.id</span></span></span></a><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"> lalu pilih jalur prestasi/organisasi/UTBK dan lengkapi formulir,dan cukup dengan&nbsp; uang pendaftaran 100.ribu.</span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"> </span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\">Untuk mendapatkan informasi lebih lanjut, bisa langsung hubungi via whatsap 087808077878 (info pendaftaran) </span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">atau instagram di </span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\"><em>@stieww_official. </em></span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Atau dapatkan informasi secara langsung dengan datang ke kampus yang beralamatkan di</span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"color:#000000\"> </span></span></span><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">&nbsp;Jl. Lowanu Sorosutan UH VI / 20, Sorosutan, Kec. Umbulharjo, Kota Yogyakarta, Daerah Istimewa Yogyakarta 55162 yang buka mulai jam 08.00 WIB.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Buruan yuk daftar sekarang, kuota terbatas hanya untuk 25 orang saja. Kapan lagi daftar kuliah pakai nilai UTBK dapat potongan. Semoga kalian bisa mendapatkan beasiswa UTBK STIE Widya Wiwaha. SBMPTN 2022 belum jodohmu, siapa tahu STIE Widya Wiwaha Jadi Awal Masa Depanmu. Kami tunggu kalian menjadi camaba STIE Widya Wiwaha 2022.</span></span></span></p>\r\n', 'Gagal SBMPTN? Ayo daftarkan skor UTBK mu di STIE Widya Wiwaha', '05-07-2022', 'news-17.png', 1, 'STIE WW', 2854, '', '', ''),
(18, 'Lowongan PT Traders Family International', 'lowongan-pt-traders-family-international', '<p>Lowongan PT Traders Family International</p>\r\n\r\n<p><img alt=\"\" src=\"http://stieww.ac.id/assets/uploads/news-18.jpg\" style=\"height:300px; width:300px\" /></p>\r\n', 'Lowongan PT Traders Family International', '07-07-2022', 'news-18.jpg', 5, 'STIE WW', 1864, '', '', ''),
(19, 'Magang Satu Kelas PT Satukelas Adhyapana Nusantara', 'magang-satu-kelas-pt-satukelas-adhyapana-nusantara', '<p>Magang Satu Kelas PT Satukelas Adhyapana Nusantara<br />\r\ninfo lebih lanjut baca selebaran dibawah ini</p>\r\n\r\n<p><a href=\"https://drive.google.com/file/d/1iDzGxUybUjVFyHB6kk4--vFvfp0fjMsR/preview\" target=\"_blank\">Magang dan Sertifikasi Digital Marketing untuk Mahasiswa</a></p>\r\n\r\n<p><a href=\"https://drive.google.com/file/d/1AbxCmEkB4T98MCwx_aeFCh-RyfKjs4Uk/preview\">Kurikulum &amp; Silabus</a></p>\r\n', 'Magang Satu Kelas PT Satukelas Adhyapana Nusantara', '01-08-2022', 'news-19.jpeg', 6, 'STIE WW', 3857, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(20, 'Gagal SBMPTN?Ayo daftarkan skor UTBK mu di  STIE Widya Wiwaha', 'gagal-sbmptn-ayo-daftarkan-skor-utbk-mu-di-stie-widya-wiwaha-1', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Lembaga Tes Masuk Perguruan Tinggi (LTMPT) telah mengumumkan hasil Seleksi&nbsp; Bersama Masuk Perguruan Tinggi (SBMPTN) 2022 pada Kamis (23/6/2022) pukul 15.00 WIB. Di Jogja sendiri terdapat lima Perguruan tinggi (PTN)&nbsp; yaitu Universitas Gadjah Mada (UGM), Universitas Negeri Yogyakarta (UNY), Universitas Pembangunan Nasional Veteran Yogyakarta (UPNVY), Institut Seni Indonesia (ISI) Yogyakarta dan Universitas Islam Negeri (UIN) Sunan Kalijaga.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">&nbsp; Sebanyak 2.716 calon mahasiswa baru dinyatakan diterima di UGM melalui jalur SBMPTN dari total&nbsp; pendaftar yaitu 50.222. Lalu, UNY keseluruhan yang diterima&nbsp; adalah sebanyak 2.334 calon mahasiswa dari total pendaftar 42.425. Kemudian, UPNVY&nbsp; sebanyak 2.448 pendaftar dinyatakan diterima dari total pendaftar 3.728.&nbsp; Selanjutnya, ISI Yogyakarta sebanyak 481 calon mahasiswa diterima dan yang terakhir adalah UIN Sunan Kalijaga, sebanyak 729 calon mahasiswa diterima.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Untuk total peserta SBMPTN tahun 2022 sendiri yakni sebanyak&nbsp; 800.852 peserta, dan yang diterima sebanyak 192.810 peserta.Yang artinya ada 608.042 pendaftar yang tidak diterima. Bagi mereka yang lolos atau tidak lolos, bisa mencetak sertifikat UTBK yang didalamnya tertera skor masing masing peserta. Bagaimana&nbsp; hasil UTBKnya<em>?</em> Selamat bagi yang diterima. Bagi kamu yang belum lulus, tak perlu berkecil hati . Gagal SBMPTN&nbsp; bukan halangan untuk kuliah atau menambah kemampuan diri. Bagi kalian yang gagal lulus SBMPTN&nbsp; tidak perlu berlarut-larut dengan hasilnya. Seperti kata pepatah Romawi &lsquo;&rsquo;Banyak jalan menuju Roma&rsquo;&rsquo; artinya masih banyak jalan untuk mencapai kesuksesan. Masih ada cara lain untuk masuk perguruan tinggi. Saat ini yang terpenting adalah bagaimana diri kita sendiri menyikapi hasil SBMPTN yang tak sesuai harapan. </span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><img src=\"data:image/jpeg;base64,\" style=\"height:287px; width:339px\" /></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Merasa sedih, itu hal&nbsp; wajar. Namun apakah kamu memang gagal? Terlepas dari pendapat orang lain, pada kenyataannya UTBK-SBMPTN hanyalah salah satu jalur masuk kuliah. Masih ada jalur-jalur lain untuk masuk kuliah. Kamu juga masih bisa mengikuti&nbsp; Seleksi Mandiri di kampus swasta. Salah satu kampus swasta di Jogja yang membuka jalur&nbsp; beasiswa dengan nilai UTBK adalah STIE Widya Wiwaha. Manfaatkan nilai UTBK mu untuk mendapatkan Beasiswa di STIE Widya Wiwaha.Yuk kuliah di STIE Widya Wiwaha dengan menggunakan skor UTBK mu jangan cuma anggurin nilainnya. </span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><img src=\"data:image/jpeg;base64,\" style=\"height:297px; width:327px\" /></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Berapa skor kamu nih? nah, jika nilai rata rata UTBK kamu lebih dari 651 maka SPA FREE atau 100% potongan SPA untukmu,dan tidak hanya itu untuk SPP sebesar 500.000 saja.. Kemudian, untuk skor rata-rata UTBK 551-650 hanya akan terkena SPA 25 %&nbsp; dengan SPP 500.000 saja. Dan selanjutnya untuk skor dengan rata- rata 451-550 hanya terkena SPA sebesar 50% dan SPP tetap. Tapi rata rata skor utbk ku dibawah 400, gimana dong? Tenang!&nbsp; Bagi yang memiliki rata-rata skor UTBK&nbsp; antara 351-450 masih bisa mendaftar dan mendapat ,potongan yaitu&nbsp; terkena SPA 75 dengan SPP tetap.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Untuk tahapan pendaftaran caranya sangat mudah yaitu mendaftarkan diri anda di website </span><a href=\"file:///C:/Users/ASUS/AppData/Roaming/Microsoft/Word/stieww.ac.id\" style=\"color:blue; text-decoration:underline\"><span style=\"font-size:12.0pt\">stieww.ac.id</span></a><span style=\"font-size:12.0pt\"> lalu pilih jalur prestasi/organisasi/UTBK dan lengkapi formulir,dan cukup dengan &nbsp;uang pendaftaran 100.ribu.</span> <span style=\"font-size:12.0pt\">Untuk mendapatkan informasi lebih lanjut, bisa langsung hubungi via whatsap 087808077878 (info pendaftaran) </span><span style=\"font-size:12.0pt\">atau instagram di <em>@stieww_official. </em>Atau dapatkan informasi secara langsung dengan datang ke kampus yang beralamatkan di</span> <span style=\"font-size:12.0pt\">&nbsp;Jl. Lowanu Sorosutan UH VI / 20, Sorosutan, Kec. Umbulharjo, Kota Yogyakarta, Daerah Istimewa Yogyakarta 55162 yang buka mulai jam 08.00 WIB.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Buruan yuk daftar sekarang, kuota terbatas hanya untuk 25 orang saja. Kapan lagi daftar kuliah pakai nilai UTBK dapat potongan. Semoga kalian bisa mendapatkan beasiswa UTBK STIE Widya Wiwaha. SBMPTN 2022 belum jodohmu, siapa tahu STIE Widya Wiwaha Jadi Awal Masa Depanmu. Kami tunggu kalian menjadi camaba STIE Widya Wiwaha 2022.</span></span></span></p>\r\n', 'Daftar saja di STIE Widya Wiwaha', '02-08-2022', 'news-20.jpg', 1, 'STIE WW', 2689, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(21, 'MUSIC EVENT LUSTRUM 8 STIE WIDYA WIWAHA', 'music-event-lustrum-8-stie-widya-wiwaha', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Amasis MT Pro&quot;,serif\">Sekolah Tinggi Ilmu Ekonomi Stie Widya Wiwaha atau yang dikenal dengan STIE WW tepat pada Tanggal 17 Juni 2022 berusia 40 Tahun,untuk mengucapkan rasa syukur atas 40 Tahun kampus STIE WW mengadakan acara LUSTRUM 8 .Untuk memeriahkan acara Ulang Tahun STIE WIDYA WIWAHA YOGYAKARTA yang ke -40 mempersembahkan Acara MUSIC EVEN dimana acara ini adalah puncak dari acara LUSTRUM 8.&nbsp;</span></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Amasis MT Pro&quot;,serif\">Acara ini menghadirkan&nbsp; Andri TTM,Putri Andien ,Putri DN dan Pembawa acaranya&nbsp; DUO KEMPLU.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Amasis MT Pro&quot;,serif\">Harga tiket untuk dapat mengikuti acara ini mulai dari RP15.000-20.000.setiap pembelian tiket dapat melalui&nbsp; Adhimsyah mia dan panitia lustrum,Acara ini dimulai pukul 18.00-selesai.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Amasis MT Pro&quot;,serif\">Dengan begitu banyaknya rangkaian acara yang disiapkan pastinya STIE WIDYA WIWAHA juga sudah mempersiapkan semuanya&nbsp; dengan matang ,dimana dapat dilihat dari awal acara sudah banyak panitia yang mengatur setiap kegiatan yang ada ,panitia sendiri merupakan mahasiswa dan mahasiswi STIE WW .</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Amasis MT Pro&quot;,serif\">Acara Music even ini juga berjalan dengan baik walaupun di guyur hujan tetapi antusias para penonton sangat besar,sehingga acara dapat berjalan dengan dengan lancar .</span></span></span></span></p>\r\n', 'Sekolah Tinggi Ilmu Ekonomi Stie Widya Wiwaha atau yang dikenal dengan STIE WW tepat pada Tanggal 17 Juni 2022 berusia 40 Tahun,untuk mengucapkan rasa syukur atas 40 Tahun kampus STIE WW mengadakan acara LUSTRUM 8 .Untuk memeriahkan acara Ulang Tahun STIE WIDYA WIWAHA YOGYAKARTA yang ke -40 mempersembahkan Acara MUSIC EVEN dimana acara ini adalah puncak dari acara LUSTRUM 8.', '02-08-2022', 'news-21.jpg', 1, 'STIE WW', 1527, '', '', ''),
(22, 'Dies Natalis STIE Widya Wiwaha ke-40 Gelar Kajian Bersama', 'dies-natalis-stie-widya-wiwaha-ke-40-gelar-kajian-bersama', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">Masih dalam rangka Dies Natalis STIE Widya Wiwaha atau Lustrum 8. Panitia juga menyelenggarakan kajian umum yang bertema &quot;Quarter Life Crisis&quot;. Kajian tersebut dilaksanakan setelah senam pagi yaitu pada pukul 10.00 WIB. Dihadiri oleh dosen, karyawan, mahasiswa STIE Widya Wiwaha dan masyarakat sekitar. Untuk susunan acaranya dibacakan oleh MC yaitu Saudari Betti dan Intan.&nbsp; Yang pertama adalah pembukaan dan dilanjutkan pembacaan ayat suci Al-Qur&#39;an atau tilawah Al-Qur&#39;an oleh Saudari Eva. Acara selanjutnya yaitu sambutan ketua STIE Widya Wiwaha, Bapak Drs. Subkhan, M.M. Dalam sambutannya beliau menyampaikan tentang sejarah dan pendiri STIE Widya Wiwaha Yogyakarta. Setelah sambutan, acara selanjutnya yaitu pengajian inti yang disampaikan oleh Ustadz Ransi Al Indragiri. Dengan tema kajian &quot;Quarter Life Crisis&quot;, beliau menyampaikan bahwa &quot;kata nabi, krisis dunia itu penyebabnya cinta dunia dan cinta harta, maka dari itu kita perlu mempelajari Al-Qur&#39;an. Dengan membaca, menghafal, memahami dengan baik dan benar makna yang terkandung dalam Al-Qur&#39;an serta mengamalkannya dalam kehidupan sehari-hari. Al-Qur&#39;an adalah obat penyembuh atau asy-Syifa&nbsp; bagi semua penyakit hati. Baik berupa syahwat yang menghalangi manusia untuk taat kepada syariat atau syubhat yang mengotori iman. Al-Qur&#39;an juga memberikan ketenangan kepada kita. Generasi Qurani adalah generasi yang menjadikan Al-Qur&#39;an sebagai pedoman hidup.&quot; Setelah kajian inti selesai, acara selanjutnya adalah sesi tanya jawab bagi para hadirin. Dan terakhir adalah penutup yang dibacakan oleh MC. Acara kajian ini selesai pukul 11.15 WIB. </span></span></p>\r\n', 'Masih dalam rangka Dies Natalis STIE Widya Wiwaha atau Lustrum 8. Panitia juga menyelenggarakan kajian umum yang bertema \"Quarter Life Crisis\". Kajian tersebut dilaksanakan setelah senam pagi yaitu pada pukul 10.00 WIB. ', '02-08-2022', 'news-22.jpg', 1, 'STIE WW', 1909, '', '', ''),
(23, 'PERAN MAHASISWA DALAM PERANGI SAMPAH', 'peran-mahasiswa-dalam-perangi-sampah', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Sampah merupakan salah satu permasalahan terbesar yang ada di Indonesia yang masih sangat sulit di atasi ,bahkan pada tahun 2021 Kementerian Lingkungan Hidup dan Kehutanan (KLHK) mencatat, Indonesia menghasilkan sebanyak 21,88 juta ton sampah. Dengan permasalahan Sampah ini Indonesia menjadi negara&nbsp; penyumbang sampah plastik terbesar kedua di dunia.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Fakta ini&nbsp; dikuatkan oleh data yang diperoleh dari Asosiasi Industri Plastik Indonesia (INAPLAS) dan Badan Pusat Statistik (BPS), yang menyatakan bahwa 3,2 juta ton sampah yang dibuang ke laut adalah sampah plastik. Kantong plastik yang terbuang ke lingkungan sebanyak 10 miliar lembar per tahun atau sebanyak 85.000 ton kantong plastik.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Sampah merupakan Hal penting yang harus segera diatasi ,karena itu semua kalangan harus dapat bekerja sama untuk perangi sampah. Peran mahasiswa sendiri sangat dibutuhkan dalam perangi sampah,karena Mahasiswa diharapkan membawa pergerakan perubahan ke arah yang lebih baik.&nbsp;&nbsp; Pada dasarnya, isu lingkungan ini tidak akan pernah terselesaikan apabila kurangnya tingkat partisipasi masyarakat. Maka dari itu, seringkali mahasiswa yang termasuk generasi muda berperan sebagai panutan masyarakat umum dalam menjaga kelestarian lingkungan. </span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Bagaimana si cara mahasiswa untuk membantu memberantas sampah yang ada diIndonesia?</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Hal utama yang dapat dilakukan adalah memanfaatkan media sosial,karena hampir semua kalangan saat ini menggunakan media sosial.karena itu mahasiswa dapat memanfaatkan itu untuk&nbsp; mengedukasi masyarakat tentang pentingnya menjaga lingkungan sekitar ,khususnya tentang sampah.membuat konten konten semenarik mungkin tentang peduli lingkungan dan sampah,yang dapat menarik perhatian masyarakat .walaupun aksi tersebut termasuk sederhana tetapi tidak menutup kemungkinan bisa membawa perubahan.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Yang dapat di lakukan oleh Mahasiswa selanjutnya adalah menerapkan 3R.3R merupakan singkatan dari Reduce(mengurangi sampah),Reuse (menggunakan ulang sampah ),dan Recycle(Daur ulang sampah) Dengan ini mahasiswa dapat mengurangi penggunaan bahan yang sulit didaur ulang seperti plastik. Bukan hanya mengurangi timbulan sampah, Mahasiswa juga dapat memanfaatkan sampah organik seperti sisa makanan dan sayuran di bawah sebagai pupuk kompos. Kegiatan mendaur ulang sampah menjadi barang baru yang bernilai guna juga menjadi opsi yang harus dicoba. Dengan ini Mahasiswa dapat mencoba merangkai sampah bekas bungkus kemasan menjadi beragam jenis tas, vas bunga, dan lain-lain. </span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Dan yang terakhir yang dapat dilakukan mahasiswa adalah Bergabung menjadi anggota Bank Sampah.Berdasarkan Pasal 1 Peraturan Menteri Lingkungan Hidup dan Kehutanan Nomor 14 Tahun 2021 tentang Pengelolaan Sampah pada Bank Sampah, bank sampah merupakan fasilitas untuk mengelola sampah dengan prinsip 3R (reduce, reuse, dan recycle), sebagai sarana edukasi, perubahan perilaku dalam pengelolaan sampah, dan pelaksanaan ekonomi sirkular, yang dibentuk dan dikelola oleh masyarakat, badan usaha, dan/atau pemerintah daerah. Mahasiswa dapat mencari tahu sebaran lokasi bank sampah yang berada di wilayah sekitar tempat tinggal masing-masing. Melalui bank sampah, Mahasiswa bisa menyetorkan sampah yang telah dipilah dan mendapatkan imbalan rupiah. Dan uang yang didapatkan bisa di simpan untuk masyarakat kembali.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Itulah beberapa langkah sederhana yang dapat dilakukan Mahasiswa dalam membantu pemerintah perangi sampah.Sebagai generasi muda Indonesia memang sudah sewajarnya kita peduli akan lingkungan dan menjaga kelestarian lingkungan ,hal ini bukan hanya berdampak pada diri sendiri namun juga orang banyak.</span></span></p>\r\n', 'Sampah merupakan salah satu permasalahan terbesar yang ada di Indonesia yang masih sangat sulit di atasi, bahkan pada tahun 2021 Kementerian Lingkungan Hidup dan Kehutanan (KLHK) mencatat, Indonesia menghasilkan sebanyak 21,88 juta ton sampah. Dengan permasalahan Sampah ini Indonesia menjadi negara  penyumbang sampah plastik terbesar kedua di dunia.', '02-08-2022', '', 1, 'STIE WW', 27260, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(24, 'SEJARAH STIE WIDYA WIWAHA', 'sejarah-stie-widya-wiwaha', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">STIE Widya Wiwaha Yogyakarta telah berkiprah selama 40 tahun di dunia pendidikan perguruan tinggi dan telah memiliki lebih dari 11.000 alumni, dengan menerapkan sistem pembelajaran yang berkualitas ditunjang dengan fasilitas yang mumpuni berakibat dapat menghasilkan lulusan yang mampu bersaing di dunia kerja, berpikir kreatif, inovatif serta visioner.<br />\r\nSTIE Widya Wiwaha merupakan Kampus Pencetak Pengusaha Era Digital yang memiliki program alternatif skripsi berupa <em>business start-up</em> untuk mahasiswa yang memiliki <em>passion</em> di bidang wirausaha serta magang untuk mahasiswa yang memilih menjadi profesional atau bekerja di perusahaan. Nah tidak hanya itu, STIE Widya Wiwaha juga memiliki berbagai program beasiswa loh, diantaranya ada P3U, Hafidz Quran, Influencer-Entrepreneur &amp; E-sport, Prestasi &amp; Organisasi, UTBK serta KIP-K.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Tetapi tahu kah kamu kampus kita STIE Widya Wiwaha kapan berdiri?</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">STIE Widya Wiwaha didirikan pada tanggal 17 Juni 1982 di bawah pengelolaan Yayasan Widya Wiwaha dengan ijin operasional Kopertis Wilayah V Yogyakarta Nomor: 206/KOPV/02/VI/84. Yayasan Widya Wiwaha didirikan pada tanggal 6 Mei 1982, berdasarkan akte notaris Umar Syamhudi, SH, nomor 4, tanggal 6 Mei 1982. Pendiri yayasan Widya Wiwaha terdiri dari tujuh orang dengan mayoritas latar belakang disiplin ilmu ekonomi, yaitu :</span></span></span></span></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">K.H. Syaiful Mudjab (Alm)</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Prof. Dr. H. Asip F. Hadipranata, Psi.</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Drs. H. Ahmadi Anwar, MM. (Alm)</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Dr. H. Muhammad Su&rsquo;ud, SE, MM.</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Drs. H. Ayik Muhammad Al-Hasny, MM.</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Prof. Dr. H. Mas&rsquo;ud Machfoedz, MBA, Ak. (Alm)</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Drs. H. Irfan Nursasmita, Msi, Akt.</span></span></span></span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:186px; width:299px\" /></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Status Terdaftar diperoleh pada tahun 1988 dengan Surat Keputusan Direktorat Jenderal Pendidikan tinggi untuk dua jurusan yaitu : </span></span></span></span></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Jurusan Manajemen dengan konsentrasi</span></span></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Pemasaran dan Jurusan Akuntansi </span></span></span></span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Status Diakui diperoleh pada tanggal 11 Agustus 1992 dengan Surat Keputusan nomor 355/ DIKTI/Kep./1992. Kemudian Status Disamakan diperoleh pada tanggal 19 Desember 1994 berdasarkan Surat Keputusan Menteri Pendidikan dan Kebudayaan Republik Indonesia dengan Surat Keputusan No. 322/DIKTI/Kep./1994. Berdasarkan Keputusan Menteri P &amp; K No. 78/D/0/1997. STIE Widya Wiwaha memperoleh status terakreditasi dengan sertifikasi BAN-PT No. 001/BAN-PT/AK-I/VIII/1998. Akreditasi tersebut sudah diperbaharui tahun 2004 dan 2008. Pada tahun 2007, STIE Widya Wiwaha membuka program studi Pasca Sarjana Magister Manajemen dengan ijin operasional SK Nomor 2785/ D/T/K-V/2009. Untuk semua program studi S-1 Akuntansi, S-1 Manajemen dan S-2 Magister Manajemen mendapatkan status TERAKREDITASI. Dengan status terakreditasi ini maka STIE Widya Wiwaha telah memenuhi standar mutu pendidikan di Indonesia. Ijin operasional program S-1 Akuntansi dan S-1 Manajemen telah diperpanjang tahun 2011 dengan nomor 7999/ D/T/K-V/2011 untuk jurusan Manajemen, dan jurusan Akuntansi dengan nomor 8000/D/T/K-V/2011. Tahun 2019, jurusan Manajemen berdasarkan SK BAN-PT No.3887/SK/BAN-PT/Akred/S/X/2019 dinyatakan terakreditasi B. Pada tahun yang sama, jurusan Akuntansi juga mendapatkan akreditasi B sesuai dengan SK BAN-PT No Sk : 3206/SK/BAN-PT/Akred/S/VIII/2019. Pada tahun 2016 STIE Widya Wiwaha memperoleh Akreditasi Institusi dengan Nilai B dengan dengan SK BAN-PT No.1100/SK/BAN-PT/Ak-PPJ/PT/XII/2021, berlaku sampai dengan 25 November 2026.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Sertifikat Akreditasi</span></span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:212px; width:298px\" /></span></span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">https://sapto.banpt.or.id/c/053004/47306</span></span></span></span></p>\r\n', 'STIE Widya Wiwaha Yogyakarta telah berkiprah selama 40 tahun di dunia pendidikan perguruan tinggi dan telah memiliki lebih dari 11.000 alumni, dengan menerapkan sistem pembelajaran yang berkualitas ditunjang dengan fasilitas yang mumpuni berakibat dapat menghasilkan lulusan yang mampu bersaing di dunia kerja, berpikir kreatif, inovatif serta visioner.\r\nSTIE Widya Wiwaha merupakan Kampus Pencetak Pengusaha Era Digital yang memiliki program alternatif skripsi berupa business start-up untuk mahasiswa yang memiliki passion di bidang wirausaha serta magang untuk mahasiswa yang memilih menjadi profesional atau bekerja di perusahaan. Nah tidak hanya itu, STIE Widya Wiwaha juga memiliki berbagai program beasiswa loh, diantaranya ada P3U, Hafidz Quran, Influencer-Entrepreneur & E-sport, Prestasi & Organisasi, UTBK serta KIP-K.', '02-08-2022', 'news-24.jpg', 1, 'STIE WW', 4010, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(25, 'Rayakan Lustrum Ke 8, STIE Widya Wiwaha Yogyakarta adakan senam pagi', 'rayakan-lustrum-ke-8-stie-widya-wiwaha-yogyakarta-adakan-senam-pagi', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Dalam rangka memperingati Dies Natalis STIE Widya Wiwaha Yogyakarta ke-40 atau Lustrum 8. Panitia menyelenggarakan senam pagi yang dilaksanakan pada hari Jum&#39;at tepatnya tanggal 17 Juni 2022 bertempat di belakang Masjid Baitusallam. Senam dimulai pukul 07.00 WIB. Yang diikuti oleh mahasiswa, karyawan, dosen serta dibuka untuk umum juga. Dalam kegiatan tersebut, siapapun yang mengikuti senam akan diberikan kaos gratis. Sebelum acara senam dimulai, ada sambutan dari ketua panitia Lustrum 8 yaitu Lantang Apriadi. Acara selanjutnya senam pagi yang dipimpin oleh instruktur senam dari Cristin Jogja. Semua yang mengikuti senam sangat bersemangat dan senang. Senam ini dimaksudkan untuk membangun kebersamaan dan semangat baik mahasiswa, dosen, karyawan maupun untuk masyarakat sekitar. Senam berakhir pukul 08.00 WIB.</span></span></span></p>\r\n', 'Dalam rangka memperingati Dies Natalis STIE Widya Wiwaha Yogyakarta ke-40 atau Lustrum 8. Panitia menyelenggarakan senam pagi yang dilaksanakan pada hari Jum\'at tepatnya tanggal 17 Juni 2022 bertempat di belakang Masjid Baitusallam', '02-08-2022', 'news-25.jpg', 1, 'STIE WW', 1410, '', '', ''),
(26, 'DIES NATALIS STIE WIDYA WIWAHA KE-40 GELAR LOMBA MTQ', 'dies-natalis-stie-widya-wiwaha-ke-40-gelar-lomba-mtq', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Masih dalam rangka Dies Natalis STIE Widya wiwaha atau Lustrum 8.panitia juga menyelengarakan lomba MTQ SE-DIY dan JATENG, perlombaan tersebut dilaksanakan pada hari jumaat pukul 13:00 WIB.dan berakhir pukul 16:00 WIB. Adapun acara tersebut dihadiri oleh panitia dan dewan juri.ada pun tata tertip peserta yang harus dipertahatikan adalah: peserta sudah berada di arena lomba 30 menit sebelum acara dimulai dan di dampingi oleh guru pendamping, peserta lomba dipanggil berdasarkan nomor undian peserta lomba, diperkenankan memakai pakaian koko,batik atau pakaian yang secara khusus dibuat untuk acara MTQ.pembukaan dibacakan oleh Nadia dan kata sambutan oleh ketua panitia, dan pak Subkhan,.MM,.kordinatornya adalah Jalu dan Muamar. Tujuan diselenggarakannya MTQ diharapkan dapat menjadi pintu gerbang bagi para peserta untuk terus menggali dan memahami.apa makna dari acara MTQ itu.</span></span></span></span></p>\r\n', 'Masih dalam rangka Dies Natalis STIE Widya wiwaha atau Lustrum 8.panitia juga menyelengarakan lomba MTQ SE-DIY dan JATENG, perlombaan tersebut dilaksanakan pada hari jumaat pukul 13:00 WIB.dan berakhir pukul 16:00 WIB.', '02-08-2022', 'news-26.jpg', 1, 'STIE WW', 1590, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(27, 'TIPS MEMBAGI WAKTU KULIAH DAN ORGANISASI', 'tips-membagi-waktu-kuliah-dan-organisasi', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Sibuk kuliah bukan berarti tidak bisa aktif dalam berorganisasi. Berorganisasi dapat dijalankan oleh setiap mahasiswa asalkan pandai&nbsp;membagi waktu&nbsp;antara kuliah dan kegiatan lain. Kamu dapat mengikuti satu atau bahkan lebih kegiatan organisasi dengan membagi waktu secara tepat. Kegiatan ini dapat disesuaikan dengan perkuliahan, karena bagaimana pun kuliah tetap merupakan prioritas utama sebagai mahasiswa. Ada waktu untuk kuliah, mengerjakan tugas, mengikuti rapat organisasi, beristirahat, dan&nbsp;refreshing agar tidak stres.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Tetapi sering kali terjadi dalam berorganisasi, kita malah jadi susah dalam membagi waktu antara tugas kuliah dengan tanggung jawab dari organisasi yang dijalani. </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Apa saja cara agar kita bisa fokus ke banyak hal? Bagaimana membagi waktu antara kegiatan satu dan lainnya? </span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Nah, kali ini mari sama-sama membahas bagaimana sih tips membagi waktu antara kuliah dan organisasi. Yuk simak ya!</span></span></span></span></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Menentukan Prioritas</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:153px; width:229px\" /></span></span></p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Tentukanlah kegiatan yang benar-benar menjadi prioritas anda. Kuliah atau organisasi? Jawabannya ada pada diri anda sendiri. Kembali lagi pada tujuan utama Anda kuliah atau ikut organisasi. Tidak ada yang salah jika Anda ingin memprioritaskan salah satunya. Sejatinya, tujuan utama seorang mahasiswa adalah untuk kuliah dan lulus tepat waktu. Namun, tidak bisa dipungkiri bahwa organisasi membantu bersosialisasi di masyarakat, terlebih kalau organisasi tersebut sesuai dengan hobi. Anda dapat memilih</span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"> organisasi yang bisa membuat nyaman dan dapat mengembangkan potensi yang ada pada diri kita. </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Untuk menentukan keputusan yang besar, setidaknya anda butuh masukan dari orang lain. </span></span></span></span></p>\r\n\r\n<ol start=\"2\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Manajemen Waktu yang Baik</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\">&nbsp;</p>\r\n\r\n<table align=\"left\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"height:0px; width:26px\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td><img alt=\"Cara Mengatur Waktu Kuliah Sambil Kerja Agar Seimbang – Pintek Blog\" src=\"data:image/jpeg;base64,\" style=\"height:178px; width:295px\" /></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Jika sudah memilih mana hal yang diprioritaskan maka selanjutnya selesaikan satu persatu pekerjaan kalian</span></span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">. Membagi dan mengatur waktu antara organisasi belajar dan aktivitas sosial merupakan sebuah hal yang wajib dilakukan. Meski demikian, banyak dari kita yang hingga saat ini masih terkendala untuk membagi aktivitas akademik dengan organisasi kampus. Terkadang jadwal kuliah yang bentrok dengan organisasi sehingga harus memilih antara salah satunya. Jika hal itu terjadi </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">kamu bisa mengatur ulang jadwal organisasi mu. Kalau tidak bisa maka kamu harus memilih salah satu diantara keduanya, dan melihat apakah kegiatan organisasi itu sangat penting bagi kamu atau tidak. Apabila terjadi jadwal kuliah bentrok, prioritaskan kuliah.</span></span></span></span></p>\r\n\r\n<ol start=\"3\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Jangan Menunda Pekerjaan</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Kebiasaan mahasiswa adalah senang menunda pekerjaan. Ini adalah sebuah kebiasaan buruk untuk Anda. Efeknya mungkin tidak terasa saat ini tetapi akan terasa di masa depan. Saat kita mengerjakan dalam waktu yang mepet makan hasilnya tidak akan maksimal. Bila Anda sudah masuk ke dalam sebuah organisasi atau komunitas masyarakat dan Anda diberi amanah untuk menjalankan kepemimpinan. Hal itu juga akan membuat diri kita menjadi pribadi yang tidak disiplin dan lamban dalam mengerjakan tugas. Maka jangan pernah menunda pekerjaan tersebut. </span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"color:black\">Pastikan pekerjaan sudah sesuai dan terarah sehingga semuanya benar-benar terselesaikan sesuai dengan waktu yang telah ditentukan.</span></span></span></span></span></p>\r\n\r\n<ol start=\"4\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Berani Menolak Kegiatan Yang Tidak Penting</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:28px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Dalam membagi waktu antara banyak kegiatan yang dilakukan pasti ada kalanya kita bingung dalam menentukan kegiatan mana yang bermanfaat atau tidak. Terkadang kita juga senang menunda bahkan meninggalkan hal yang seharusnya penting dan melakukan hal yang kurang penting. Saat kamu diajak untuk menghabiskan waktu kita untuk yang tidak penting, kita harus berani menolaknya. Ketika berani menolak sesuatu maka menunjukkan kekuatan dan ketangguhanmu terhadap suatu hal. &nbsp;</span></span></span></span></p>\r\n\r\n<ol start=\"5\">\r\n	<li style=\"text-align:justify\">\r\n	<table>\r\n		<tbody>\r\n			<tr>\r\n				<td style=\"height:0px; width:26px\">&nbsp;</td>\r\n			</tr>\r\n			<tr>\r\n				<td>&nbsp;</td>\r\n				<td><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:159px; width:253px\" /></span></span></td>\r\n			</tr>\r\n		</tbody>\r\n	</table>\r\n	<br />\r\n	<span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Fokus Pada Tujuan Dan Masa Depan</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Salah satu tips dan cara membagi waktu antara kuliah dan organisasi kampus secara maksimal adalah dengan motivasi. Salah satunya dengan cara merencanakan masa depan dengan organisasi dan jurusan kuliah yang sudah anda pilih. Paling tidak saat Anda menentukan prioritas itu artinya Anda sudah memiliki bayangan masa depan yang akan dijalankan nanti. Tentu saja hal ini semakin membuat Anda semangat agar bisa memaksimalkan setiap waktu supaya tidak terbuang secara percuma.</span></span></span></span></p>\r\n\r\n<ol start=\"6\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Jalin Komunikasi yang Efektif</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Bila Anda ingin menyampaikan sebuah hal yang mendesak namun tidak bisa mengkomunikasikan dengan baik. Anda bisa dibilang gagal sebagai pribadi yang baik dimata orang lain. Misalnya besok diadakan ujian tengah semester. Nah di jam yang sama organisasi yang diikuti menuntut Anda untuk wajib hadir di agenda rapat yang penting. Di sinilah pentingnya Anda dalam berkomunikasi. Tentu saja dalam hal ini Snda lebih memprioritaskan kuliah. Anda bisa izin tidak bisa hadir mengikuti rapat karena kuliah. </span></span></span></span></p>\r\n\r\n<ol start=\"7\">\r\n	<li style=\"text-align:justify\">\r\n	<table>\r\n		<tbody>\r\n			<tr>\r\n				<td style=\"height:0px; width:29px\">&nbsp;</td>\r\n			</tr>\r\n			<tr>\r\n				<td>&nbsp;</td>\r\n				<td><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:157px; width:187px\" /></span></span></td>\r\n			</tr>\r\n		</tbody>\r\n	</table>\r\n	<br />\r\n	<span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Totalitas Diri</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:26px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Di dalam kuliah maupun sebuah organisasi Anda harus punya totalitas diri yang terbaik. Bila Anda di dalam sebuah organisasi maka sebaiknya saat itu pula organisasikan diri Anda untuk masuk ke organisasi. Begitu pula dengan kuliah, sebaiknya Anda selalu fokus dan total dalam mata kuliah yang dipelajari. Saat Anda memiliki totalitas diri yang baik, maka Anda dapat menarik perhatian orang lain dengan kepribadian Anda yang total. Dalam hal ini yang diperlukan untuk awal totalitas diri yaitu keberanian dan juga keyakinan Anda untuk mencoba sehingga kempuan dan keberanian juga akan berkembang.</span></span></span></span></p>\r\n\r\n<ol start=\"8\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Evaluasi Setiap Kegiatan Yang Dilakukan</span></span></strong></span></span>\r\n\r\n	<table>\r\n		<tbody>\r\n			<tr>\r\n				<td style=\"height:0px; width:28px\">&nbsp;</td>\r\n			</tr>\r\n			<tr>\r\n				<td>&nbsp;</td>\r\n				<td><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><img src=\"data:image/jpeg;base64,\" style=\"height:170px; width:255px\" /></span></span></td>\r\n			</tr>\r\n		</tbody>\r\n	</table>\r\n	<span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"> </span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:28px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Setiap kegiatan yang telah dilakukan baik itu kuliah ataupun organisasi perlu adanya evaluasi. Apakah kita telah melakukannya secara optimal atau apa saja hal yang menghambat kegiatan tersebut. Hal itu perlu adanya evaluasi sehingga kedepannya kita bisa memilih kegiatan mana saja yang sebaiknya dilakukan dan tidak dilakukan. </span></span></span></span></p>\r\n\r\n<p style=\"margin-left:28px; text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">B</span></span><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">agaimana teman-teman, ternyata sangat mudah ya cara membagi waktu kuliah dan organisasi? Jadi, kalian bisa menerapkannya mulai dari sekarang ya. Jangan ragu, untuk bisa kuliah sambil berorganisasi. Karena, kalian akan merasakan manfaat keduanya saat masuk dalam dunia kerja.&nbsp;So, jangan ragu untuk mencoba cara diatas ya!</span></span></span></span></p>\r\n', 'Sibuk kuliah bukan berarti tidak bisa aktif dalam berorganisasi. Berorganisasi dapat dijalankan oleh setiap mahasiswa asalkan pandai membagi waktu antara kuliah dan kegiatan lain. Kamu dapat mengikuti satu atau bahkan lebih kegiatan organisasi dengan membagi waktu secara tepat. Kegiatan ini dapat disesuaikan dengan perkuliahan, karena bagaimana pun kuliah tetap merupakan prioritas utama sebagai mahasiswa. Ada waktu untuk kuliah, mengerjakan tugas, mengikuti rapat organisasi, beristirahat, dan refreshing agar tidak stres.', '02-08-2022', 'news-27.jpg', 1, 'STIE WW', 13251, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(28, 'LIBURAN SEMESTER MAU NGAPAIN?', 'liburan-semester-mau-ngapain-', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">LIBURAN SEMESTER MAU NGAPAIN?&nbsp;</span></span></strong></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">YUK LAKUKAN HAL INI AGAR LIBURAN JADI PRODUKTIF!</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Liburan semester dalam perkuliahan atau sekolah, biasanya mendapatkan liburan yang panjang bahkan sampai 3 bulan. Ketika mendapatkan libur panjang, apakah hanya makan tidur makan tidur? Terus kira-kira apa aja sih yang bisa kita lakukan saat libur panjang?</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Berikut beberapa rekomendasi kegiatan yang bisa kamu lakukan agar liburanmu semester tetap produktif.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Yuk simak penjelasan nya</span></span></span></span></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Mempersiapkan Semester Baru</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Mungkin dari temen-temen udah mulai masuk ke sekolah atau kuliah lagi , bisa banget pakai momen ini untuk mempersiapkan semester baru. Misalnya udah mulai mendekati waktu masuk, liburan ini dapat digunakan secara produktif dengan mempersiapkan baru ini jadi misalnya membeli buku dan peralatan tulis baru, mencari info tentang kelas yang ingin diikutin semester depan atau mencari buku referensi untuk menambah wawasan kita. Karena dengan perencanaan yang matang akan terasa nyaman saat melakukannya.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img src=\"data:image/jpeg;base64,\" style=\"height:207px; width:265px\" /></span></span></span></span></p>\r\n\r\n<ol start=\"2\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Meluangkan Waktu Bersama Keluarga dan Teman</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Selama liburan jangan hanya sibuk melakukan hal-hal yang kalian suka tapi kalian harus meluangkan waktu bersama keluarga dan teman-teman. Memberikan waktu khusus untuk bercerita bersama keluarga, berlibur bersama keluarga atau melakukan hal-hal sederhana lainnya sehingga waktu libur menjadi lebih berharga. Selain itu juga sesekali pergi liburan bersama teman kalian,&nbsp; jalan-jalan, dan bercerita. Nikmati apa yang kalian lakukan jadi selama kalian ngelakuin kegiatan-kegiatan yang bermanfaat.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<ol start=\"3\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Magang kampus</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Disaat liburan semester seperti sekarang kampus juga memberi ruang untuk mahasiswa khususnya yang mendapat beasiswa untuk dapat magang dikampus sekaligus membantu kampus dalam melaksanakan seluruh kegiatan. Salah satu contohnya adalah kampus STIE WIDYA WIWAHA Yogyakarta yang mulai memberi ruang bagi mahasiswa untuk dapat berpartisipasi dalam membantu dari mulai&nbsp; PMB (pengenalan mahasiswa baru), Kemahasiswaan,Prodi dll. Kegiatan itu saat ini menjadi kegiatan yang harus dilakukan setiap minggunya oleh mahasiswa terkhusus bidang PMB untuk menghidupkan kampus lewat berbagai macam sosial media. </span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img src=\"data:image/jpeg;base64,\" style=\"height:164px; width:312px\" /></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<ol start=\"4\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Mengikuti berbagai macam organisasi</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Organisasi bisa kita ikuti tidak hanya di kampus saja, diluar kampus juga kita bisa berorganisasi. Dengan kita ikut berbagai macam kegiatan organisasi maka kita bisa belajar, memperbanyak ilmu, memperbanyak pertemanan&nbsp; serta dapat mengisi waktu luang. Kegiatan organisasi&nbsp; di kampus tidak ikut libur juga, tetap ada aktivitas yang dilakukan seperti rapat besar tentang apa yang akan dilakukan setelah kuliah offline, kegiatan yang akan terlaksana, dan anggaran yang harus di persiapkan. Dengan hal ini maka waktu yang kita punya tidak akan sia sia dikarenakan adannya kegiatan organisasi yang masih terlaksana.</span></span></span></span></p>\r\n\r\n<ol start=\"5\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Mengasah skill berbicara dan bahasa</span></span></strong></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Ada banyak keuntungan jika kamu melatih kemampuan berbicara dan bahasamu dari sekarang. Hal itu bisa meningkatkan skill public speaking dan juga menambah wawasanmu terkait kebahasaan. Meski kelihatannya cukup sepele, hal seperti ini sebenarnya sangat penting untuk kehidupanmu selanjutnya. </span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img src=\"data:image/jpeg;base64,\" style=\"height:168px; width:252px\" /></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<ol start=\"6\">\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Rapikan dan tata ulang meja belajarmu</span></span></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:52px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Suasana meja belajar berpengaruh terhadap kegiatan belajar kita. Agar tidak mudah bosan dan merasa jenuh, kita bisa memanfaatkan waktu liburan untuk merapikan dan tata ulang meja belajar. Kita bisa mengganti suasana menjadi berbeda, seperti mengubah susunan, atau menambah dan mengurangi barang-barang tertentu.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img src=\"data:image/jpeg;base64,\" style=\"height:186px; width:251px\" /></span></span></span></span></p>\r\n', 'Liburan semester dalam perkuliahan atau sekolah, biasanya mendapatkan liburan yang panjang bahkan sampai 3 bulan. Ketika mendapatkan libur panjang, apakah hanya makan tidur makan tidur? Terus kira-kira apa aja sih yang bisa kita lakukan saat libur panjang?', '02-08-2022', 'news-28.jpg', 1, 'STIE WW', 7156, '', '', '');
INSERT INTO `tbl_news` (`news_id`, `news_title`, `news_slug`, `news_content`, `news_content_short`, `news_date`, `photo`, `category_id`, `publisher`, `total_view`, `meta_title`, `meta_keyword`, `meta_description`) VALUES
(29, 'PROSIDING Seminar Nasional dan Call Paper, Tema: “Strategi Pemulihan UMKM Pasca Pandemi Covid”', 'prosiding-seminar-nasional-dan-call-paper-tema-strategi-pemulihan-umkm-pasca-pandemi-covid-', '<p style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong>Halaman Depan, Sambutan Panitia, Sambutan Ketua STIE Widya Wiwaha,&nbsp;</strong><a href=\"https://drive.google.com/file/d/1G7mUJRbqomYkOtF0FXc49B78f3TpGXhu/view?usp=sharing\" target=\"_blank\">Klik Disini</a></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><strong>Daftar isi Artikel</strong></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Political Skill, Lingkungan Kerja Dan Motivasi Pada Kinerja. <strong>Dwi Novitasari, </strong><a href=\"http://eprint.stieww.ac.id/1741/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Digital Marketing Terhadap Citra Smk Bumantara Muntilan Kabupaten Magelang. <strong>Hendrix Tiyas Eka Kusuma, </strong><a href=\"http://eprint.stieww.ac.id/1742/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Optimalisasi Bhabinkamtibmas Terhadap <em>Tour Of Duty</em> Dan <em>Tour Of Area</em> Di Polres Magelang. <strong>Sunandar, </strong><a href=\"http://eprint.stieww.ac.id/1743/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Motivasi Dan Beban Kerja Terhadap Kinerja Karyawan Dengan Kepuasan Kerja Sebagai Variabel Mediasi (Studi pada Karyawan Outsourcing di RSUP Dr. Sardjito). <strong>Arsanto Darmawan dan Suhartono, </strong><a href=\"http://eprint.stieww.ac.id/1744/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Pusat Kegiatan Gugus Dan Sertifikasi Terhadap Peningkatan Literasi Digital Guru Taman Kanak-Kanak Di Masa Pandemi Covid-19<em>.</em> <strong>Dwi Lestari, </strong><a href=\"http://eprint.stieww.ac.id/1745/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Pendapatan Asli Daerah, Dana Perimbangan, dan Belanja Daerah Terhadap Kinerja Keuangan Pemerintah Daerah Pada Kabupaten/Kota Di Provinsi Jawa Tengah dan DIY Tahun 2016-2020. <strong>Dyah Ayu Putri Ermawati, Nur Widiastuti dan Zulkifli, </strong><a href=\"http://eprint.stieww.ac.id/1746/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Faktor Penentu Manajemen Laba. <strong>Fatonah dan Taswan, </strong><a href=\"http://eprint.stieww.ac.id/1747/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Sistem Pengendalian Intern Pemerintah Dan Aksesibilitas Laporan Keuangan Terhadap Akuntabilitas Pengelolaan Keuangan Dana Desa (Studi Kasus Kelurahan Margokaton Kabupaten Sleman Yogyakarta). <strong>Lilik Ambarwati dan Ulva Nur Novia Handayani, </strong><a href=\"http://eprint.stieww.ac.id/1748/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Ekonomi Digital Di Indonesia, Peluang Dan Strategi. <strong>Nur Widiastuti, </strong><a href=\"http://eprint.stieww.ac.id/1749/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Strategi Inovasi: Bagaimana Usaha Kecil Perempuan Bisa Bertahan Hidup Di Masa Pandemi. <strong>Priyastiwi, </strong><a href=\"http://eprint.stieww.ac.id/1750/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Work From Home (WFH) Dan Kepuasan Kerja Terhadap Produktivitas Kerja.<strong>Riska Anggelina dan Uswatun Chasanah, </strong><a href=\"http://eprint.stieww.ac.id/1751/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Efektifitas Peran Kader Di Kelompok Kegiatan BKB Melati 9 RW 9 Kelurahan Warungboto Kemantren Umbulharjo Kota Yogyakarta<em>. </em><strong>Yulia Suryani Dewi, </strong><a href=\"http://eprint.stieww.ac.id/1752/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Distribusi, Promosi Dan Kualitas Layananan Terhadap Keputusan Pembelian Pada Online Shop Shopee Selama Pandemi Covid-19. <strong>Lubna Laila dan Nita Fitriana, </strong><a href=\"http://eprint.stieww.ac.id/1753/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Profitabilitas, Likuiditas, Ukuran Perusahaan, Dan Leverage Terhadap Pengungkapan Internet <em>Financial Reporting</em> Pada Perusahaan Indeks LQ45 Yang Terdaftar Di Bursa Efek Indonesia (BEI) Periode Tahun 2015-2019. <strong>Sulastiningsih dan Ajeng Fazri Rahmasari, </strong><a href=\"http://eprint.stieww.ac.id/1754/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pemberdayaan, Motivasi Dan Peningkatan Kinerja Karyawan Pada Masa Pandemi Covid-19 (Studi Kasus Pada Toko Beibyqu-Baby Shop Bantul Yogyakarta). <strong>Futri Khairunnisah dan Evi Rosalina Widyayanti, </strong><a href=\"http://eprint.stieww.ac.id/1755/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Literasi Keuangan, Digital Marketing, Brand Image Dan Word Of Mouth Terhadap Minat Generasi Z Pada Bank Syariah (Studi Kasus Di Bank Syariah Kabupaten Sleman). <strong>Muhammad Subkhan dan Muhammad Yusli, </strong><a href=\"http://eprint.stieww.ac.id/1760/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Analisis SWOT dan TOWS Dalam Menentukan Strategi Keberlanjutan Usaha Dapur Warna di Era New Normal. <strong>Ratih Safitri Sulistyowati dan Qurrata A&rsquo;yunina C.H,&nbsp;</strong></span></span><a href=\"http://eprint.stieww.ac.id/1786/\" target=\"_blank\">Klik Disini</a></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Penerapan Strategi Business Model Canvas (BMC) Dalam Upaya Bertahan Hidup UMKM Dimasa Pandemi Covid-19 Di Daerah Istimewa Yogyakarta. <strong>Evi Rosalina</strong> <strong>Widyayanti dan Insiatiningsih</strong>,&nbsp;</span></span><a href=\"http://eprint.stieww.ac.id/1782/\" target=\"_blank\">Klik Disini</a></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Strategi Pemasaran, Inovasi Produk, Dan Minat Beli Untuk Meningkatkan Kinerja Pemasaran Umkm Pada Pedagang Kaki Lima Pakaian Batik Di Malioboro. <strong>Muhammad Robi Nurwahyudi dan Mareta Windi Astuti</strong>,&nbsp;</span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Peran E-Learning Training Dan Motivasi Pada Kinerja Pegawai Di Masa Pandemi Covid-19. <strong>Sofiati dan Dewi Larasati</strong>, </span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Analisis Anteseden Dan Konsekuen Kepuasan Pelanggan Pada Rumah Makan Cepat Saji Dengan Pendekatan Teori Stimulus-Organism-Response (SOR). <strong>Muhammad Mathori dan Uswatun Chasanah,</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Kualitas Pelayanan Terhadap Kepuasan Konsumen (Studi Pada Pengguna Transportasi Online Di Daerah Istimewa Yogyakarta). <strong>Linawati</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Kinerja Lingkungan Dan Pengungkapan Informasi Lingkungan Terhadap Kinerja Keuangan (Studi Empiris Pada Perusahaan Tambang Yang Terdaftar Di Bei Tahun 2017-2019). <strong>Lilis Ari Yulianti, Hasanah dan Siti Endarwati,</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Analisis Kebijakan Perusahaan Melakukan Revaluasi Aset Tetap (Studi Empiris pada Perusahaan Perbankan yang Terdaftar di Bursa Efek Indonesia Tahun 2015-2019). <strong>Ratna Haninditya Sari, Manendha Maganitri Kundala, dan Raden Papang Permadi,</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\">Pengaruh Suku Bunga Kredit Mikro Dan Jaminan Terhadap Keputusan Pengambilan Kredit Mikro Pada Pelaku UMKM Di Yogykarta. <strong>Yunita Fitri Wahyuningtyas dan Sigit Dwi Putro,</strong></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">Hubungan Antara Adversity Quotient Dengan Prestasi Belajar Pada Siswa XI Man 3 Yogyakarta.&nbsp;<strong>Qurrata A&rsquo;yunina C.H. dan Syaiyidatul Achmad Marzuki,&nbsp;</strong><a href=\"http://eprint.stieww.ac.id/1871/\" target=\"_blank\">Klik Disini</a></span></span></li>\r\n</ul>\r\n', 'PROSIDING Seminar Nasional dan Call Paper, Tema: “Strategi Pemulihan UMKM Pasca Pandemi Covid”', '07-09-2022', 'news-29.png', 7, 'STIE WW', 3983, '', '', ''),
(30, 'Lowongan Kerja Unitama', 'lowongan-kerja-unitama', '<p>Lowongan Kerja Unitama</p>\r\n', 'Lowongan Kerja Unitama', '29-07-2024', 'news-30.jpeg', 5, 'STIE Widya Wiwaha', 1929, '', '', ''),
(31, 'LP2M STIE Widya Wiwaha Yogyakarta Tandatangani Kontrak dengan Dosen Penerima Pendanaan Hibah Penelitian dan Pengabdian Masyarakat Tahun Anggaran 2025', 'lp2m-stie-widya-wiwaha-yogyakarta-tandatangani-kontrak-dengan-dosen-penerima-pendanaan-hibah-penelitian-dan-pengabdian-masyarakat-tahun-anggaran-2025', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><strong><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Yogyakarta, 2 Juli 2025</span></span></strong><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">&nbsp;<span style=\"font-family:Times New Roman\">&mdash; LP2M Sekolah Tinggi Ilmu Ekonomi (STIE) Widya Wiwaha Yogyakarta resmi menandatangani kontrak dengan dosen penerima pendanaan hibah Penelitian dan Pengabdian kepada Masyarakat Tahun Anggaran 2025 yang didanai oleh Direktorat Penelitian dan Pengabdian kepada Masyarakat (DPPM), Direktorat Jenderal Riset dan Pengembangan Kementerian Pendidikan Tinggi, Sains, dan Teknologi (Ditjen Risbang Kemdiktisaintek).</span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Hibah Penelitian dan Pengabdian kepada Masyarakat ini merupakan bagian dari strategi nasional dalam meningkatkan kualitas riset dan kontribusi nyata perguruan tinggi, termasuk Perguruan Tinggi Swasta (PTS). Para dosen STIE Widya Wiwaha akan melaksanakan program-program yang difokuskan pada pemecahan persoalan di masyarakat, khususnya dalam bidang ekonomi, kewirausahaan, serta pengembangan Usaha Mikro, Kecil, dan Menengah (UMKM).</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Capaian ini mencerminkan pengakuan terhadap kualitas akademik dosen STIE Widya Wiwaha. Meskipun mayoritas tenaga pengajar masih berkualifikasi Magister (S2), mereka telah menunjukkan performa yang setara dengan dosen bergelar doktor dalam hal metodologi penelitian, kedalaman analisis, serta kemampuan implementasi program pengabdian. </span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Partisipasi dalam program ini diharapkan dapat memperkuat budaya riset dan inovasi di lingkungan kampus, memperluas jejaring antar institusi, serta mendorong kolaborasi lintas sektor. Selain itu, melalui kegiatan pengabdian, hasil-hasil penelitian juga diarahkan untuk dapat diimplementasikan secara langsung di masyarakat, sehingga memberikan dampak nyata di tengah perubahan ekonomi yang terus berlangsung.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">STIE Widya Wiwaha menyatakan komitmennya untuk terus mendukung peningkatan kapasitas akademik dosen, serta memastikan bahwa setiap hasil riset yang dihasilkan mampu memberikan kontribusi positif bagi pembangunan masyarakat.</span></span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><strong><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Informasi lebih lanjut dapat diperoleh melalui:</span></span></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial\"><strong><span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Humas STIE Widya Wiwaha</span></span></strong><br />\r\n<span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Alamat: Jl. Lowanu Sorosutan UH VI/20 Yogyakarta 55162</span></span><br />\r\n<span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Email: info@stieww.ac.id</span></span><br />\r\n<span style=\"font-size:12.0000pt\"><span style=\"font-family:\'Times New Roman\'\">Telepon: (0274) 377091</span></span></span></span></p>\r\n', 'LP2M STIE Widya Wiwaha Yogyakarta Tandatangani Kontrak dengan Dosen Penerima Pendanaan Hibah Penelitian dan Pengabdian Masyarakat Tahun Anggaran 2025', '10-07-2025', 'news-31.jpeg', 1, 'Widya Wiwaha', 928, 'LP2M STIE Widya Wiwaha Yogyakarta Tandatangani Kontrak dengan Dosen Penerima Pendanaan Hibah Penelitian dan Pengabdian Masyarakat Tahun Anggaran 2025', '', ''),
(32, 'Muhadhoroh dan Pelepasan Santri Asrama Al-Fatih STIE Widya Wiwaha', 'muhadhoroh-dan-pelepasan-santri-asrama-al-fatih-stie-widya-wiwaha', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Yogyakarta, 17 Juli 2025 &mdash; Asrama Al-Fatih STIE Widya Wiwaha menggelar acara </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><em>Muhadhoroh dan Pelepasan Santri</em></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> sebagai bentuk apresiasi dan penghormatan bagi para santri yang telah menyelesaikan masa tinggal dan pembinaan selama satu tahun penuh. Acara yang diselenggarakan di kampus STIE Widya Wiwaha ini berlangsung meriah, sarat makna, dan penuh emosi.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Kegiatan diawali dengan pembukaan dan sambutan dari Ketua STIE Widya Wiwaha, dilanjutkan dengan sesi </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><em>muhadhoroh</em></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> yang diisi oleh seluruh santri dengan tema </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Kesehatan Mental, Dukungan Mental dan </strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong><em>Stop Bullying</em></strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">. Unjuk bakat menjadi salah satu inti acara, dimana para santri menampilkan beragam kreativitas seperti pembacaan puisi, drama pendek, pantomim, menyanyi, hingga ceramah yang memukau</span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong><em>.</em></strong></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Puncak acara ditandai dengan prosesi </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><em>pelepasan santri</em></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> yang telah menyelesaikan masa tinggalnya di asrama. Suasana haru menyelimuti ruangan saat satu per satu santri dipanggil ke depan untuk menerima </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>sertifikat penghargaan</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> sebagai bentuk pengakuan atas ketekunan, kedisiplinan, dan semangat belajar selama berada di lingkungan asrama Al-Fatih.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Muhadhoroh dan pelepasan ini menjadi momen penting yang tak hanya menandai selesainya satu fase pembinaan, namun juga menginspirasi para santri untuk terus tumbuh menjadi pribadi yang berilmu, berakhlak mulia, dan siap memberi kontribusi positif di mana pun berada.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<hr />\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\"><strong>Humas STIE Widya Wiwaha</strong></span></span></span><br />\r\n<span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Alamat: Jl. Lowanu Sorosutan UH VI/20 Yogyakarta 55162</span></span></span><br />\r\n<span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Email: info@stieww.ac.id</span></span></span><br />\r\n<span style=\"font-size:12pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Whatsapp: 08780807787</span></span></span></p>\r\n', 'Muhadhoroh dan Pelepasan Santri Asrama Al-Fatih STIE Widya Wiwaha', '21-07-2025', 'news-32.jpg', 1, 'Widya Wiwaha', 818, '', '', ''),
(33, 'Mempererat Ukhuwah dan Silaturahmi Akademika STIE Widya Wiwaha', 'mempererat-ukhuwah-dan-silaturahmi-akademika-stie-widya-wiwaha', '<h3><span style=\"font-size:13pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>PRESS RELEASE</strong></span></span></span></h3>\r\n\r\n<h3><span style=\"font-size:13pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>&ldquo;Mempererat Ukhuwah dan Silaturahmi Akademika STIE Widya Wiwaha&rdquo;</strong></span></span></span></h3>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Yogyakarta, 1 Agustus 2025</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> &mdash; Dalam rangka membangun kebersamaan, semangat Qur&rsquo;ani dan meningkatkan kedekatan antar sesama dosen dan karyawan, STIE Widya Wiwaha menggelar kegiatan </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Sima&rsquo;an Al-Qur&rsquo;an</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> yang melibatkan mahasiswa, dosen, serta civitas akademika lainnya. Acara ini menjadi momentum spiritual sekaligus sosial yang menyentuh, menghadirkan suasana tenang dan penuh makna di tengah kesibukan akademik.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Kegiatan sima&rsquo;an yang berlangsung di kampus STIE Widya Wiwaha ini dilaksanakan dengan format sederhana namun khusyuk: Gus Umam membaca ayat-ayat suci Al-Qur&rsquo;an, sementara peserta lainnya menyimak dengan khidmat. Tak hanya menjadi ajang mendengarkan bacaan Al-Qur&rsquo;an, kegiatan ini juga menjadi ruang belajar bersama, saling memperbaiki bacaan, dan mempererat tali silaturahmi.</span></span></span></p>\r\n\r\n<h3><span style=\"font-size:13pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Sima&rsquo;an: Bukan Sekadar Mendengar, Tapi Menghidupkan Hati</strong></span></span></span></h3>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Sima&rsquo;an Al-Qur&rsquo;an berasal dari kata &quot;sama&rsquo;a&quot; yang berarti mendengar. Namun dalam konteks ini, bukan hanya mendengar biasa. Ini adalah </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>mendengarkan dengan hati</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">, dengan niat mendekat kepada Allah SWT. Dalam Al-Qur&rsquo;an, Allah berfirman:</span></span></span></p>\r\n\r\n<p style=\"margin-left:40px; margin-right:40px\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><em>&quot;Dan apabila dibacakan Al-Qur&rsquo;an, maka dengarkanlah dan diamlah agar kamu mendapat rahmat.&quot;</em></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> (QS. Al-A&rsquo;raf: 204)</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Kegiatan seperti ini menjadi penting sebagai </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>pengingat ruhiyah di tengah tantangan era digital</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">. Tidak sedikit dari kita yang sibuk dengan tugas, organisasi, atau bahkan media sosial. Melalui sima&rsquo;an, kita diajak untuk meluangkan waktu khusus, merenung, dan memperbaiki hubungan kita dengan Al-Qur&rsquo;an.</span></span></span></p>\r\n\r\n<h3><span style=\"font-size:13pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Manfaat Langsung bagi Anak Muda</strong></span></span></span></h3>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Menurut panitia kegiatan, sima&rsquo;an ini memberikan banyak manfaat khususnya untuk generasi muda:</span></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Membangun cinta pada Al-Qur&rsquo;an</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">: Mendengarkan teman sendiri membaca bisa menjadi motivasi untuk ikut belajar dan menghafal.</span></span></span><br />\r\n	&nbsp;</li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Melatih fokus dan ketenangan jiwa</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">: Sesi mendengarkan bacaan Al-Qur&rsquo;an membantu kita melatih konsentrasi dan menemukan ketenangan.</span></span></span><br />\r\n	&nbsp;</li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Menjadi sarana muhasabah diri</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">: Setiap ayat yang dibacakan bisa menjadi cermin untuk memperbaiki akhlak dan cara hidup kita.</span></span></span><br />\r\n	&nbsp;</li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Menumbuhkan rasa saling mendukung antar teman</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">: Ketika satu membaca dan yang lain menyimak serta memberi koreksi dengan adab, tumbuhlah suasana belajar bersama yang sehat dan suportif.</span></span></span><br />\r\n	&nbsp;</li>\r\n</ul>\r\n\r\n<h3><span style=\"font-size:13pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Penutup</strong></span></span></span></h3>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Kegiatan sima&rsquo;an Al-Qur&rsquo;an di STIE Widya Wiwaha bukan hanya kegiatan keagamaan, tetapi menjadi simbol bahwa </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>ukhuwah, silaturahmi, dan semangat Qur&rsquo;ani</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> bisa tumbuh subur di lingkungan akademik. Remaja dan mahasiswa sebagai generasi penerus bangsa patut dibekali bukan hanya dengan ilmu dunia, tapi juga kekuatan ruhani yang kokoh.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Mari jaga semangat Qur&rsquo;ani. Karena dari hati yang tenang, akan lahir karya dan prestasi yang gemilang</strong></span></span></span></p>\r\n', 'Mempererat Ukhuwah dan Silaturahmi Akademika STIE Widya Wiwaha', '01-08-2025', 'news-33.jpeg', 1, 'Widya Wiwaha', 833, '', '', ''),
(34, 'Aksi Sosial Manna', 'aksi-sosial-manna', '<p>Program sosial Manna Kampus menghadirkan bantuan pendidikan dan lingkungan untuk warga sekitar.</p>', 'Program sosial Manna Kampus menghadirkan bantuan pendidikan dan lingkungan untuk warga sekitar.', '15-08-2026', 'social6.png', 8, 'Manna Kampus', 0, 'Aksi Sosial Manna', 'social, community, impact', 'Berita kegiatan sosial Manna Kampus.'),
(35, 'Kegiatan Donasi Pendidikan untuk Anak Desa', 'donasi-pendidikan-anak-desa', '<p>Manna Kampus membuka donasi buku dan alat tulis untuk sekolah-sekolah desa yang kekurangan fasilitas.</p>', 'Manna Kampus membuka donasi buku dan alat tulis untuk sekolah-sekolah desa yang kekurangan fasilitas.', '18-08-2026', 'social5.png', 8, 'Manna Kampus', 0, 'Donasi Pendidikan', 'social, education, donation', 'Berita donasi pendidikan warga desa.'),
(36, 'Gotong Royong Bersihkan Lingkungan Sekitar', 'gotong-royong-bersihkan-lingkungan', '<p>Relawan Manna Kampus mengadakan gotong royong membersihkan lingkungan sekitar dan melakukan pengolahan sampah organik.</p>', 'Relawan Manna Kampus mengadakan gotong royong membersihkan lingkungan sekitar dan melakukan pengolahan sampah organik.', '20-08-2026', 'social4.png', 8, 'Manna Kampus', 2, 'Gotong Royong Lingkungan', 'social, environment, community', 'Berita kegiatan gotong royong lingkungan.'),
(37, 'Pelatihan Kewirausahaan untuk Pemuda Lokal', 'pelatihan-kewirausahaan-pemuda-lokal', '<p>Pemuda lokal mengikuti pelatihan kewirausahaan untuk membuka peluang usaha berbasis komunitas.</p>', 'Pemuda lokal mengikuti pelatihan kewirausahaan untuk membuka peluang usaha berbasis komunitas.', '22-08-2026', 'social3.png', 8, 'Manna Kampus', 8, 'Pelatihan Kewirausahaan', 'social, entrepreneurship, youth', 'Berita pelatihan kewirausahaan pemuda lokal.'),
(38, 'Aksi Bagi Sembako untuk Keluarga Pra-Sejahtera', 'aksi-bagi-sembako-keluarga-pra-sejahtera', '<p>Manna Kampus membagikan paket sembako kepada keluarga prasejahtera di lingkungan kampus dan sekitarnya.</p>', 'Manna Kampus membagikan paket sembako kepada keluarga prasejahtera di lingkungan kampus dan sekitarnya.', '24-08-2026', 'social2.png', 8, 'Manna Kampus', 11, 'Pembagian Sembako', 'social, aid, community', 'Berita aksi pembagian sembako.'),
(39, 'Kampanye Kesehatan Gratis bagi Warga Sekitar', 'kampanye-kesehatan-gratis-warga-sekitar', '<p>Tim kesehatan Manna Kampus menggelar pemeriksaan kesehatan gratis dan edukasi gizi untuk warga sekitar.</p>', 'Tim kesehatan Manna Kampus menggelar pemeriksaan kesehatan gratis dan edukasi gizi untuk warga sekitar.', '26-08-2026', 'social1.png', 8, 'Manna Kampus', 9, 'Kampanye Kesehatan', 'social, health, outreach', 'Berita kampanye kesehatan gratis.');

